BoFGuide_Defer("Lang_koKR", function()
BoFGuide_Localize({
  locale = "koKR",
  lines = {
    ["'Badwind' Bennic is deep in the bandits' cave. Its mouth hides behind a waterfall."] = "'Badwind' Bennic은(는) 산적 동굴 깊숙이 있어요. 동굴 입구는 폭포 뒤에 숨어 있어요.",
    ["3 furbolgs ambush you halfway along the tunnel, and 3 more at the village entrance. Start at full health."] = "터널 중간에서 퍼볼그 3마리가, 마을 입구에서 3마리가 더 습격해요. 생명력을 가득 채우고 시작하세요.",
    ["A Blacksmith makes the Golden Rod: buy one at the Auction House, or ask one."] = "금마법막대는 대장장이가 만들어요. 경매장에서 사거나 대장장이에게 부탁하세요.",
    ["A Blacksmith makes the Silver Rod: buy one at the Auction House, or ask one."] = "은마법막대는 대장장이가 만들어요. 경매장에서 사거나 대장장이에게 부탁하세요.",
    ["A Bloodtalon Taillasher usually stands by each egg. Kill it before you loot."] = "알마다 보통 붉은발톱랩터가 지키고 있어요. 루팅 전에 처치하세요.",
    ["A Burning Blade Crusher (13) and a Toxicologist (14) stand in the den by the altar. Pull them out one at a time."] = "불타는칼날단 전사(13)와 Toxicologist(14)가 제단 옆 소굴에 있어요. 하나씩 끌어내세요.",
    ["A Burning Blade Fanatic patrols near Fizzle, and Lightning Hides stand behind him."] = "Fizzle 근처를 불타는칼날단 광신자가 순찰하고, 그 뒤에 Lightning Hides가 서 있어요.",
    ["A Dark Iron Summoner at his side calls fire elementals."] = "곁의 Dark Iron Summoner가 불의 정령을 불러요.",
    ["A Fishing Pole costs 23 copper. Equip it and cast Fishing at the water."] = "낚싯대는 23코퍼예요. 장착하고 물을 향해 낚시를 시전하세요.",
    ["A Flutterfly that stays put after a swat wasn't caught. Swat it again."] = "때린 뒤에도 그 자리에 있는 Flutterfly는 잡히지 않은 거예요. 다시 때리세요.",
    ["A Kobold Miner stands next to Goldtooth and usually joins the fight. Expect two at once."] = "황금니 코볼트 옆에 코볼트 광부가 서 있어서 보통 같이 싸워요. 둘을 동시에 상대할 각오를 하세요.",
    ["A Lake Thresher, a level 25 elite, swims a patrol through this part of the lake. Let it pass before you dive."] = "레벨 25 정예 호수 트레샤돈이 호수의 이 구역을 헤엄치며 순찰해요. 지나간 뒤에 잠수하세요.",
    ["A Lake Thresher, a level 25 elite, swims through the lake and kills you in a few hits at this level. Dive for the toolbox only while it's on the far side."] = "레벨 25 정예 호수 트레샤돈이 호수를 헤엄쳐 다니고, 이 레벨에서는 몇 대에 죽어요. 반대편에 있을 때만 공구함을 향해 잠수하세요.",
    ["A Paladin quest: only a part of it is in this dungeon."] = "성기사 퀘스트: 이 던전에선 일부만 진행해요.",
    ["A Pitted Iron Chest under the water, where the turtles swim, holds Lorgalis' Manuscript."] = "거북이가 헤엄치는 물속의 Pitted Iron Chest에 Lorgalis' Manuscript이(가) 들어 있어요.",
    ["A Reef Shark, a level 21-22 elite, swims by this lockbox. Loot it while the shark is away."] = "레벨 21-22 정예 모래톱상어가 이 금고 옆을 헤엄쳐요. 상어가 멀리 있을 때 루팅하세요.",
    ["A Shiny Bauble or two (50 copper each) on your pole stops fish getting away from your first cast."] = "낚싯대에 반짝이는 미끼를 한두 개(개당 50코퍼) 달면 첫 시전부터 물고기가 달아나지 않아요.",
    ["A Son of Arugal (level 24-25 elite) can wander through here. Watch for it and keep clear."] = "아루갈의 후예(레벨 24-25 정예)가 이곳을 지나갈 수 있어요. 잘 보고 피하세요.",
    ["A Son of Arugal (level 24-25 elite) has been seen among the Moonrage here. Look around before each pull."] = "이곳 Moonrage 사이에서 아루갈의 후예(레벨 24-25 정예)가 목격됐어요. 풀링 전마다 주위를 보세요.",
    ["A Son of Arugal (level 24-25 elite) has been seen on the road at the north end of this loop. Keep clear of it."] = "이 순환 경로 북쪽 끝 길에서 아루갈의 후예(레벨 24-25 정예)가 목격됐어요. 피하세요.",
    ["A Son of Arugal (level 25 elite) roams from The Dead Field south to the Moonrage gnolls. Give it a wide berth."] = "아루갈의 후예(레벨 25 정예)가 죽음의 농장에서 남쪽 Moonrage 놀 쪽으로 돌아다녀요. 멀리 돌아가세요.",
    ["A Strange Lockbox in the water off this coast holds the Aquatic Agility half. Swim out to it."] = "이 해안 앞바다 물속의 Strange Lockbox에 Aquatic Agility 반쪽이 들어 있어요. 헤엄쳐 가세요.",
    ["A Swoop's knockdown interrupts the rod. Use it again right away."] = "Swoop의 넘어뜨리기는 막대 사용을 끊어요. 바로 다시 사용하세요.",
    ["A Venture Co. camp sits just southwest of the well, with Enforcer Emilgund (level 11 rare). Use the totem and move on."] = "우물 바로 남서쪽에 Venture Co. 야영지가 있고, 감독관 에밀군드(레벨 11 희귀)가 있어요. 토템을 쓰고 지나가세요.",
    ["A Wandering Protector, a level 35 elite, can patrol near the western approach to Night Run. Look before you go in."] = "레벨 35 정예 방랑하는 고대수호자가 어둠의 터 서쪽 진입로 근처를 순찰할 수 있어요. 들어가기 전에 살피세요.",
    ["A Wandering Protector, a level 35 elite, walks Ursangous's path too. Look before you pull."] = "방랑하는 고대수호자(레벨 35 정예)도 우르산고우스의 길을 순찰해요. 당기기 전에 살펴보세요.",
    ["A Warlock quest: only a part of it is in this dungeon."] = "흑마법사 퀘스트예요. 이 던전에서는 일부만 진행해요.",
    ["A Warrior quest: only a part of it is in this dungeon."] = "전사 퀘스트: 이 던전에선 일부만 진행해요.",
    ["A barrier blocks Runeweaver Square. Talk to Grindle Firespark to drop it."] = "Runeweaver Square를 장벽이 막고 있어요. Grindle Firespark와 대화하면 걷혀요.",
    ["A big pack of casters stands by the tent. Pull it before you talk to him."] = "천막 옆에 시전자 무리가 크게 있어요. 그와 대화하기 전에 풀링하세요.",
    ["A buy that helps but isn't needed. Skip it if your money is short."] = "도움은 되지만 필수는 아닌 구매예요. 돈이 부족하면 건너뛰세요.",
    ["A caster and a fighter come with him. Crowd-control the Squallshaper and face him away from the group."] = "시전자 하나와 전사 하나가 함께 와요. Squallshaper는 군중 제어하고, 그는 파티 반대쪽을 보게 하세요.",
    ["A curse in the skeleton waves cuts healing taken by 75%. Remove it fast."] = "해골 웨이브의 저주는 받는 치유량을 75% 줄여요. 빨리 해제하세요.",
    ["A dungeon run: it needs a group of five. Settings can leave dungeons out."] = "던전 진행: 5인 파티가 필요해요. 설정에서 던전을 뺄 수 있어요.",
    ["A few fish get away here until skill 25: a Shiny Bauble on your pole stops that."] = "숙련도 25까지는 여기서 물고기가 가끔 달아나요. 낚싯대에 반짝이는 미끼를 달면 막을 수 있어요.",
    ["A few fish get away here until skill 75: a Shiny Bauble on your pole stops that."] = "숙련도 75까지는 여기서 물고기가 가끔 달아나요. 낚싯대에 반짝이는 미끼를 달면 막을 수 있어요.",
    ["A group quest: it's made for 2 players."] = "파티 퀘스트: 2인용이에요.",
    ["A group quest: it's made for 3 players."] = "파티 퀘스트: 3인용이에요.",
    ["A group quest: it's made for 4 players."] = "파티 퀘스트: 4인용이에요.",
    ["A group quest: it's made for 5 players."] = "파티 퀘스트: 5인용이에요.",
    ["A hidden boss and a hard one. Shadow Bolt Volley hits the whole group."] = "숨겨진 우두머리이자 어려운 우두머리예요. 연발 어둠의 화살은 파티 전체를 공격해요.",
    ["A hop on flat ground counts as well, so there's no need to drop from the tower."] = "평지에서 뛰어도 인정되니 탑에서 뛰어내릴 필요는 없어요.",
    ["A lead-in only: Gershala Nightwhisper gives Researching the Corruption without it."] = "선행 퀘스트일 뿐이에요. 이 퀘스트 없이도 게르샬라 나이트위스퍼가 타락에 대한 연구를 줘요.",
    ["A lead-in: Gershala Nightwhisper offers Researching the Corruption without it."] = "선행 퀘스트예요. 이 퀘스트 없이도 게르샬라 나이트위스퍼가 타락에 대한 연구를 줘요.",
    ["A leyline crosses the trail just north of Valanaar. Recast Read Leyline as you pass."] = "발라나르 바로 북쪽에서 지맥이 길을 가로질러요. 지나가며 지맥 읽기를 다시 시전하세요.",
    ["A leyline runs beside the thugs. Recast Read Leyline there when it runs out."] = "불량배들 옆으로 지맥이 지나가요. 끝나면 거기서 지맥 읽기를 다시 시전하세요.",
    ["A patrol walks past outside his kitchen. Kill it before you pull him."] = "그의 부엌 밖으로 순찰병이 지나가요. 그를 풀링하기 전에 처치하세요.",
    ["A ramp on the north-west side takes you up and out of the shrine."] = "북서쪽 경사로로 올라가면 성소 밖으로 나가요.",
    ["A rare Deviate Faerie Dragon may wander the caves."] = "동굴에 희귀 돌연변이 요정용이 돌아다닐 수 있어요.",
    ["A rare Large Loch Crocolisk, level 22, can lie on the east shore facing the island."] = "레벨 22 희귀 큰 호수악어가 섬을 마주한 동쪽 해안에 있을 수 있어요.",
    ["A rare dwarf, Bruegal Ironknuckle, is sometimes in a cell in the west hall."] = "희귀 드워프 브루갈 아이언너클이 가끔 서쪽 홀 감방에 있어요.",
    ["A rare, the Dark Iron Ambassador, can stand in the tunnel before Tinkers' Court. He casts Fireball and calls a fire add."] = "희귀 검은무쇠단 사절이 Tinkers' Court 앞 굴에 있을 수 있어요. 화염구를 쓰고 불 쫄을 불러요.",
    ["A rare, the Deathsworn Captain, can stand past Odo. He cleaves: tank him away from the group."] = "희귀 죽음의 경비대장이 Odo 너머에 있을 수 있어요. 회전베기를 쓰니 파티에서 떨어뜨려 탱킹하세요.",
    ["A short dungeon on one path. Ghosts come first, then Dark Iron dwarves."] = "한 갈래 길로 된 짧은 던전이에요. 유령이 먼저, 그다음 Dark Iron 드워프가 나와요.",
    ["A snake can come out when you pick one. Clear the area first."] = "하나 집을 때 뱀이 나올 수 있어요. 먼저 주변을 정리하세요.",
    ["A spirit wolf appears to lead the way. Following it is optional."] = "길을 안내하는 늑대 정령이 나타나요. 따라가지 않아도 돼요.",
    ["A thrown bomb or grenade pulls Ruuzel on her own, away from her escorts."] = "폭탄이나 수류탄을 던지면 루젤만 호위병에게서 떨어져 끌려와요.",
    ["Aamelia Windfield walks between two spots in Windfield Orchard, so she may not be at the arrow."] = "Aamelia Windfield은(는) 윈드필드 과수원의 두 지점을 오가서 화살표 위치에 없을 수 있어요.",
    ["Abandon and retake the quest if its 12 minutes run out before you're back."] = "돌아오기 전에 12분이 다 되면 퀘스트를 포기하고 다시 받으세요.",
    ["Abercrombie's shack stands north of Raven Hill Cemetery."] = "Abercrombie의 오두막은 까마귀 언덕 묘지 북쪽에 있어요.",
    ["About 13 Weak Flux take you to 75: /bofg shopping lists the rest."] = "약한 융해촉진제 약 13개면 75까지 올릴 수 있어요. 나머지는 /bofg shopping에 나와요.",
    ["About 25 Weak Flux take you to 75: /bofg shopping lists the rest."] = "약한 융해촉진제 약 25개면 75까지 올릴 수 있어요. 나머지는 /bofg shopping에 나와요.",
    ["About 27 Mote of Magic take you to 24: /bofg shopping lists the rest."] = "마법의 티끌 약 27개면 24까지 올릴 수 있어요. 나머지는 /bofg shopping에 나와요.",
    ["About 3 Mild Spices take you to 50: /bofg shopping lists the rest."] = "부드러운 양념 약 3개면 50까지 올릴 수 있어요. 나머지는 /bofg shopping에 나와요.",
    ["About 35 furbolgs of 23 to 24 fill Thistlefur Hold's tunnels. Clear the way to each chest."] = "레벨 23-24 퍼볼그 약 35마리가 Thistlefur Hold 굴에 가득해요. 상자마다 가는 길을 정리하세요.",
    ["About 35 stalkers of 21 to 22 fill the tunnels, and the rare Leech Widow, level 24, roams them."] = "레벨 21-22 추적자 약 35마리가 굴에 가득하고, 레벨 24 희귀 거머리과부거미가 돌아다녀요.",
    ["About 38 harpies (levels 9 to 11) crowd this camp. Pull from its edge, one at a time."] = "레벨 9-11 하피 약 38마리가 이 야영지에 몰려 있어요. 가장자리에서 하나씩 풀링하세요.",
    ["About 40 Defias Pillagers and Looters (levels 13 to 15) fill Moonbrook. Clear around each crate before you open it."] = "Defias Pillager와 Looter 약 40명(레벨 13-15)이 문브룩에 가득해요. 상자를 열기 전에 주위를 정리하세요.",
    ["About 50 troggs of 16 to 18 fill the cave, and Goggeroc is a level 20 elite. Bring a partner."] = "레벨 16-18 트로그 약 50마리가 동굴에 가득하고, 고게로크는 레벨 20 정예예요. 동료를 데려가세요.",
    ["About 64 Coarse Thread take you to 66: /bofg shopping lists the rest."] = "굵은 실타래 약 64개면 66까지 올릴 수 있어요. 나머지는 /bofg shopping에 나와요.",
    ["About 74 Coarse Thread take you to 75: /bofg shopping lists the rest."] = "굵은 실타래 약 74개면 75까지 올릴 수 있어요. 나머지는 /bofg shopping에 나와요.",
    ["About 87 Empty Vial take you to 75: /bofg shopping lists the rest."] = "유리 약병 약 87개면 75까지 올릴 수 있어요. 나머지는 /bofg shopping에 나와요.",
    ["About a dozen Terrowulf worgen of 28 to 30 and the rare Packlord (32) crowd round the tome."] = "레벨 28-30 Terrowulf 늑대인간 열두 마리쯤과 희귀 Packlord(32)이(가) 고서 주위에 모여 있어요.",
    ["About a minute of sitting by the fire gives Boosted Rest and completes it."] = "모닥불 옆에 1분쯤 앉아 있으면 휴식 강화를 얻고 완료돼요.",
    ["About seven Forsaken of 28 to 30 hold the camp, and some of them hide in stealth."] = "레벨 28-30 Forsaken 일곱 명쯤이 야영지를 지키고, 일부는 은신해 있어요.",
    ["Achellios the Banished, a level 31 rare centaur with hounds, and Rok'Alim the Pounder, a level 30 elite, roam the canyon between the harpies and Highperch."] = "추방자 아킬리오스(레벨 31 희귀 켄타우로스, 개를 데리고 다님)와 돌주먹 로크알림(레벨 30 정예)이 하피와 마루둥지 사이 협곡을 돌아다녀요.",
    ["Aean Swiftriver, a level 26 rare elite, can be up among the mounds. Keep well clear of him."] = "레벨 26 희귀 정예 이안 스위프트리버가 둔덕 사이에 있을 수 있어요. 멀리 피하세요.",
    ["Afadra Dunwall stands at the bottom of Old Ironforge, up the stairs by the portal."] = "Afadra Dunwall은 아이언포지 옛 구역 맨 아래, 차원문 옆 계단 위에 있어요.",
    ["Afadra is up the switchback ramp from Thom Filch."] = "Afadra은(는) Thom Filch에서 지그재그 경사로를 올라간 곳에 있어요.",
    ["Affliction"] = "고통",
    ["Affray Challengers come one at a time, back to back, before Big Will. Start at full health."] = "싸움꾼 윌 전에 Affray Challenger가 하나씩 연달아 나와요. 생명력을 가득 채우고 시작하세요.",
    ["After a short scene Stanley turns into Enraged Stanley and attacks. Hand this in at full health."] = "짧은 장면 뒤 스탠리가 광포해진 스탠리로 변해 공격해요. 생명력이 가득할 때 반납하세요.",
    ["After a short wind-up, Malfunction hits everyone within 25 yards every 2 seconds for 6 seconds."] = "잠깐 준비 동작 뒤, 기능 장애가 6초 동안 2초마다 25미터 안의 모두를 공격해요.",
    ["After each stomp he walks to his chest to change weapons. Heal up while he's away."] = "발 구르기 뒤마다 무기를 바꾸러 상자로 걸어가요. 그동안 회복하세요.",
    ["After this hand-in you can destroy the Lieutenant's Insignia."] = "이 반납 후에는 부관의 휘장을 파괴해도 돼요.",
    ["Afterwards, Walk on Air glides you from the lower peak down to Urs'endris. Only jump with it ready."] = "그다음 공중 걷기로 아래 봉우리에서 Urs'endris까지 활강해요. 준비됐을 때만 뛰어내리세요.",
    ["Agathelos the Raging"] = "흉포한 아가테로스",
    ["Ageron Kargal is upstairs in the Brill inn."] = "아제론 카갈은 브릴 여관 위층에 있어요.",
    ["Aggem Thorncurse"] = "저주의가시 아겜",
    ["Aggor the Young is a level 11 elite sea giant. Bring two friends; at about 13 a pair can handle him."] = "Aggor the Young은 레벨 11 정예 바다 거인이에요. 친구 둘을 데려가세요. 약 13레벨이면 둘로도 잡을 수 있어요.",
    ["Aggor the Young walks the shore, so he may be away from the arrow."] = "Aggor the Young은(는) 해안을 걸어 다녀서 화살표에서 멀리 있을 수 있어요.",
    ["Aim the Taming Rod at a Dire Mottled Boar from its longest range, so the cast ends before it reaches you."] = "사나운 점박이멧돼지에게 조련용 막대를 최대 사거리에서 겨누세요. 그래야 다가오기 전에 시전이 끝나요.",
    ["Aim the Taming Rod at a Surf Crawler from its longest range."] = "붉은톱니게에게 조련용 막대를 최대 사거리에서 겨누세요.",
    ["Aim the Taming Rod at an Armored Scorpid from its longest range."] = "등껍질전갈에게 조련용 막대를 최대 사거리에서 겨누세요.",
    ["Akeri Duskblade stands inside the watchtower."] = "Akeri Duskblade은(는) 감시탑 안에 있어요.",
    ["Aku'mai"] = "아쿠마이",
    ["Alamar Grimm is on Anvilmar's upper floor."] = "알라마 그림은 앤빌마 위층에 있어요.",
    ["Alba Fairmoon offers this once you've done Sprite Jumpsprocket's dynamite errands in Stormwind."] = "스톰윈드에서 Sprite Jumpsprocket의 다이너마이트 심부름을 마치면 Alba Fairmoon이 이 퀘스트를 줘요.",
    ["Alba waits outside the Deadmines' back exit, on the coast below Moonbrook."] = "Alba는 죽음의 폐광 뒷출구 밖, 문브룩 아래 해안에서 기다려요.",
    ["Alchemy 1-225"] = "연금술 1-225",
    ["Aldia is on an upper floor in Dolanaar."] = "알디아는 돌라나르의 위층에 있어요.",
    ["Alina and Dermot are inside the ruin at the marker. Ricter waits outside it."] = "앨리나와 더모트는 표시된 폐허 안에 있어요. 릭터는 그 밖에서 기다려요.",
    ["Alliance"] = "얼라이언스",
    ["Almost every enemy is immune to Arcane. Arcane spells, Arcane Shot and Counterspell won't work."] = "거의 모든 적이 비전 면역이에요. 비전 주문, 신비한 사격, 마법 차단이 통하지 않아요.",
    ["Alterac Mountains and Stranglethorn Vale are nearly as good for this."] = "알터랙 산맥과 가시덤불 골짜기도 이 용도로 거의 비슷해요.",
    ["Alterac Mountains, Thousand Needles and Arathi Highlands are nearly as good for this."] = "알터랙 산맥, 버섯구름 봉우리, 아라시 고원도 이 용도로 거의 비슷해요.",
    ["Alvarion Windfield is upstairs, one floor up inside the house."] = "Alvarion Windfield은(는) 집 안 한 층 위에 있어요.",
    ["Alyissia is inside Aldrassil's base, up the ramp past the vendors."] = "알리시아는 알드랏실 밑동 안, 상인들을 지나 경사로 위에 있어요.",
    ["Amara paces the road out of Dolanaar to the west. Look along it if she isn't at the arrow."] = "Amara은(는) 돌라나르에서 서쪽으로 나가는 길을 오가요. 화살표 위치에 없으면 길을 따라 찾아보세요.",
    ["Amara walks the road west out of Dolanaar. If furbolgs ambush her, talk to her once the fight ends."] = "Amara은(는) 돌라나르에서 서쪽으로 난 길을 걸어요. 퍼볼그가 그녀를 습격하면 싸움이 끝난 뒤 대화하세요.",
    ["Ambercorns lie under trees. The Well Stones are on the ground by the Winterhoof Water Well."] = "Ambercorn은(는) 나무 아래에 있어요. Well Stone은(는) 윈터후프 우물 옆 땅에 있어요.",
    ["Ambush with a dagger (the Curvewood Dagger works) opens hard on each tower guard. Slower than sneaking, far safer."] = "단검으로 매복(굽이나무 단검도 돼요)을 쓰면 탑 경비병마다 강하게 시작할 수 있어요. 몰래 지나가기보다 느리지만 훨씬 안전해요.",
    ["Ambushes only come while you're on the main road. Walk beside it instead."] = "습격은 큰길 위에 있을 때만 와요. 길 옆으로 걸으세요.",
    ["An Elemental Convergence is right here. Cast Skysight before you leave for 10% run speed."] = "바로 여기에 정기의 합일이 있어요. 떠나기 전에 창공안을 시전하면 이동 속도 10%.",
    ["An Elemental Convergence lies on the way in from Missionary Jasaan. Recast Skysight there."] = "Missionary Jasaan 쪽에서 들어오는 길에 정기의 합일이 있어요. 거기서 창공안을 다시 시전하세요.",
    ["An Elemental Convergence sits among the High Order Apprentices. Recast Skysight there."] = "High Order Apprentice 사이에 정기의 합일이 있어요. 거기서 창공안을 다시 시전하세요.",
    ["An Elemental Convergence sits in the orchard. Cast Skysight there for 10% run speed."] = "과수원에 정기의 합일이 있어요. 거기서 창공안을 시전하면 이동 속도가 10% 올라요.",
    ["An Old History Book can drop from almost any Duskwood mob. Use it from your bags to start this."] = "오래된 역사책은 거의 모든 그늘숲 몹에게서 드랍될 수 있어요. 가방에서 사용해 시작하세요.",
    ["An elite Lake Thresher swims a patrol over the Lost Tools. Wait for it to pass before you dive."] = "Lost Tools 위로 정예 호수 트레샤돈이 순찰하며 헤엄쳐요. 지나간 뒤 잠수하세요.",
    ["An outdoor dungeon. Stay out of the tall grass. Hidden raptors spawn in it and join any fight."] = "야외 던전이에요. 키 큰 풀에 들어가지 마세요. 숨은 랩터가 생겨나 싸움에 끼어들어요.",
    ["Anastasia Hartwell is in the Magic Quarter."] = "아나스타샤 하트웰은 Magic Quarter에 있어요.",
    ["Anaya Dawnrunner walks a patrol through Ameth'Aran and respawns slowly. Check back if she's gone."] = "아나야 돈러너는 아메스아란 안을 순찰하고 다시 생성되는 데 오래 걸려요. 없으면 나중에 다시 확인하세요.",
    ["Ander Solliden walks the road south of the keep. Look along it if he isn't at the arrow."] = "Ander Solliden은(는) 성채 남쪽 길을 걸어요. 화살표 위치에 없으면 길을 따라 찾아보세요.",
    ["Andron's Bookshelf stands right behind Andron Gant."] = "Andron's Bookshelf은(는) 안드론 건트 바로 뒤에 있어요.",
    ["Angerclaw Grizzly (LvL. 52), Felpaw Wolf (LvL. 48), Angerclaw Bear (LvL. 48). About 19 skins on a 10-spot loop."] = "성난발톱불곰 (LvL. 52), 악령발늑대 (LvL. 48), 성난발톱곰 (LvL. 48). 10곳을 도는 순환로에서 가죽 약 19개.",
    ["Angerclaw Grizzly, Felpaw Wolf, Angerclaw Bear"] = "성난발톱불곰, 악령발늑대, 성난발톱곰",
    ["Anilia stands in the middle of Xavian's satyrs, 28 to 30. Clear your way to her one pull at a time."] = "아닐리아는 레벨 28~30 사비안 사티로스 한가운데 서 있어요. 하나씩 풀링하며 길을 뚫으세요.",
    ["Anti-Venom needs First Aid 80 and one Small Venom Sac, from Duskwood's Venom Web and Pygmy Venom Web Spiders."] = "해독제에는 응급치료 80개와 작은 독주머니 하나가 필요해요. 그늘숲의 Venom Web Spider와 Pygmy Venom Web Spider에게서 얻어요.",
    ["Anti-Venom removes Touch of Zanzil. Left alone, it lasts 7 days."] = "해독제는 잔질의 손길을 없애요. 그냥 두면 7일 동안 지속돼요.",
    ["Antur Fallow stands at the arch west of Camp Narache. Take the road south out of the camp and round the crater to him."] = "안투르 팰로우는 나라체 야영지 서쪽의 아치에 서 있어요. 야영지에서 남쪽 길로 나가 분화구를 돌아 그에게 가세요.",
    ["Any Herbalism trainer teaches every rank."] = "약초채집 전문가라면 누구나 모든 단계를 가르쳐요.",
    ["Any Mining trainer teaches every rank."] = "채광 전문가라면 누구나 모든 단계를 가르쳐요.",
    ["Any Skinning trainer teaches every rank."] = "무두질 전문가라면 누구나 모든 단계를 가르쳐요.",
    ["Any fish you land can raise your skill, wherever you are."] = "어디서 낚든 물고기를 낚으면 숙련도가 오를 수 있어요.",
    ["Any of the larger rooms inside Fargodeep Mine gives the credit."] = "개미굴 광산 안의 큰 방 아무 곳에서나 인정돼요.",
    ["Any undead at Agamand Mills can drop the letter. Loot every kill there."] = "아가만드 밀농장의 언데드 누구나 편지를 드랍할 수 있어요. 거기서 잡은 건 모두 루팅하세요.",
    ["Apothecary Berard is upstairs in Pyrewood's inn. The journal is in Berard's Bookshelf beside him."] = "연금술사 베랄드는 Pyrewood 여관 위층에 있어요. 일지는 그 옆 Berard's Bookshelf에 있어요.",
    ["Apothecary Zamah is down in the Pools of Vision, under the Spirit Rise."] = "연금술사 자마는 정기의 봉우리 아래 예언의 웅덩이에 있어요.",
    ["Apothecary Zamah is in the Pools of Vision, the cave under the Spirit Rise."] = "연금술사 자마는 정기의 봉우리 아래 동굴인 예언의 웅덩이에 있어요.",
    ["Aquadynamic Fish Attractor"] = "액체역학 물고기 유인기",
    ["Aramis Hammerhand is inside the Deathknell church."] = "Aramis Hammerhand은(는) 데스넬 교회 안에 있어요.",
    ["Arathi Highlands is nearly as good for this."] = "아라시 고원도 이 용도로 거의 비슷해요.",
    ["Arathi Highlands, Hillsbrad Foothills and Thousand Needles are nearly as good for this."] = "아라시 고원, 힐스브래드 구릉지, 버섯구름 봉우리도 이 용도로 거의 비슷해요.",
    ["Arcane Anomaly"] = "비전 변형물",
    ["Arcane Nullifier X-21 sends spells back and ignores bleeds and poisons. Dark Iron Agents lay mines."] = "자동화 마력제거기 X-21은 주문을 되돌리고 출혈과 독을 무시해요. Dark Iron Agent는 지뢰를 깔아요.",
    ["Arcanic Enigma"] = "신비한 수수께끼",
    ["Arch Druid Hamuul Runetotem is on Elder Rise, Thunder Bluff's north-east mesa."] = "대드루이드 하뮬 룬토템은 썬더 블러프 북동쪽 고원인 장로의 봉우리에 있어요.",
    ["Archaeologist Flagongut is upstairs in the Deepwater Tavern, Menethil's inn."] = "고고학자 플라곤구트는 메네실 항구 여관인 깊은바다 선술집 위층에 있어요.",
    ["Archibald Kava is inside the building east of the church."] = "아키볼드 카바는 교회 동쪽 건물 안에 있어요.",
    ["Archmage Arugal"] = "대마법사 아루갈",
    ["Archmage Ataeric is inside Ambermill's town hall."] = "대마법사 아테릭은 앰버밀 마을회관 안에 있어요.",
    ["Arcing Smash hits everyone in front of him."] = "회전 강타는 앞의 모두를 맞혀요.",
    ["Arcing Smash hits everything in front of him. The tank turns him away from the group."] = "회전 강타는 앞에 있는 모두를 때려요. 탱커가 파티 반대쪽으로 돌리세요.",
    ["Arclight Spanner"] = "만능 스패너",
    ["Argent Guard Thaelrid can repair your gear."] = "은빛경비병 타엘리드에게서 장비를 수리할 수 있어요.",
    ["Armand Cromwell, the fishing trainer, stands by the canal in the Magic Quarter."] = "낚시 전문가 알만드 크롬웰은 마법 지구 운하 옆에 있어요.",
    ["Arms"] = "무기",
    ["Arnold Leland, the fishing trainer, stands by the canal in Stormwind. Catherine Leland beside him sells fishing supplies."] = "낚시 전문가 아놀드 리랜드는 스톰윈드 운하 옆에 있어요. 옆에 있는 캐서린 리랜드가 낚시용품을 팔아요.",
    ["Arra'chea circles northern Mulgore clockwise. Wait on his path if he isn't in sight."] = "알라치아는 멀고어 북부를 시계 방향으로 돌아요. 안 보이면 그의 경로에서 기다리세요.",
    ["Arra'chea is level 11 and The Rake, a level 10 rare, prowls the same ground. Take them one at a time, at full health."] = "알라치아는 레벨 11이고, 레벨 10 희귀 몹 갈퀴도 같은 곳을 돌아다녀요. 생명력을 가득 채우고 하나씩 상대하세요.",
    ["Artisan Fishing comes from Nat Pagle's quest, not a trainer."] = "전문 낚시는 전문가가 아니라 내트 페이글의 퀘스트에서 배워요.",
    ["Artisan: it needs skill 200 and level 35, as players saw in the beta."] = "장인: 기술 200, 레벨 35이 필요해요. 베타에서 플레이어들이 확인했어요.",
    ["Ashenvale"] = "잿빛 골짜기",
    ["Ashenvale Outrunners move in stealth, so you only see them up close."] = "잿빛 골짜기 정찰꾼은 은신해서 다녀서 가까이 가야 보여요.",
    ["Ashenvale and Stonetalon"] = "잿빛 골짜기와 돌발톱 산맥",
    ["Ashenvale and Stonetalon Mountains are nearly as good for this."] = "잿빛 골짜기와 돌발톱 산맥도 이 용도로 거의 비슷해요.",
    ["Ashenvale is nearly as good for this."] = "잿빛 골짜기도 이 용도로 거의 비슷해요.",
    ["Ashlan stands at the south edge of Dun Modr. The Dark Iron dwarves a few steps north are elites of 27 to 31. Come in from the south, hand in and leave the same way."] = "Ashlan은 던 모드르 남쪽 끝에 있어요. 몇 걸음 북쪽의 Dark Iron 드워프는 레벨 27-31 정예예요. 남쪽에서 들어가 반납하고 같은 길로 나오세요.",
    ["Assassination"] = "암살",
    ["Astaia, the fishing trainer, stands by the water in Darnassus. Voloren beside her sells fishing supplies."] = "낚시 전문가 아스타이아는 다르나서스의 물가에 있어요. 옆에 있는 볼로렌이 낚시용품을 팔아요.",
    ["Astor Hadren walks the road between The Sepulcher and Brill. Check along it if he isn't here."] = "아스토르 하드렌은 공동묘지와 브릴 사이 길을 걸어요. 여기 없으면 길을 따라 확인하세요.",
    ["Astranaar's guards are level 40 and attack the Horde. Keep to the arrow round the town's west side."] = "아스트라나르 경비병은 레벨 40이고 호드를 공격해요. 마을 서쪽으로 도는 화살표를 따라가세요.",
    ["Astranaar, Ashenvale"] = "아스트라나르 (잿빛 골짜기)",
    ["At 28 the Threshwackonator 4100, a level 20 elite, is a fight you can take alone."] = "레벨 28이면 Threshwackonator 4100(레벨 20 정예)은 혼자 상대할 만해요.",
    ["At Auberdine's moonwell, use the Empty Water Tube from your bags."] = "아우버다인의 달샘에서 가방의 빈 시험관을 사용하세요.",
    ["At Kodo Rock, drink the Earth Sapta to call up the Minor Manifestation of Earth."] = "코도 바위에서 대지의 정기를 마셔 하급 대지의 현신을 불러내세요.",
    ["At the Jansen Stead well, west of the Furlbrows, take a sample with the kit."] = "Furlbrow 서쪽 얀센 농장 우물에서 도구로 샘플을 채취하세요.",
    ["At the Molsen Farm well, take a sample with the kit from your bags."] = "몰센 농장 우물에서 가방의 도구로 샘플을 채취하세요.",
    ["At the Moonkin Stone in the cave, use the Cenarion Moondust. Defeat Lunaclaw, then speak to his spirit."] = "동굴의 Moonkin Stone에서 세나리온 달가루를 사용하세요. 초승달발톱을 쓰러뜨린 뒤 그의 영혼과 대화하세요.",
    ["At the pool below the waterfall, use the Empty Sampling Tube from your bags."] = "폭포 아래 웅덩이에서 가방의 빈 견본 시험관을 사용하세요.",
    ["At two-thirds and one-third health he stomps and stuns the whole group. Kill his two guards first."] = "생명력 3분의 2와 3분의 1에서 발을 굴러 파티 전체를 기절시켜요. 경호병 둘을 먼저 처치하세요.",
    ["Ataeric's hall is crowded with Dalaran casters. Draw them to the door a few at a time before you take him."] = "Ataeric의 전당에는 달라란 주문시전자가 가득해요. 그를 잡기 전에 몇 마리씩 문으로 끌어내세요.",
    ["Atrexis the Grave Knight"] = "무덤 기사 아트렉시스",
    ["Attack the easternmost wyvern and the other two vanish."] = "가장 동쪽 와이번을 공격하면 나머지 둘은 사라져요.",
    ["Auberdine, Darkshore"] = "아우버다인 (어둠의 해안)",
    ["Austil de Mon is inside the Brill inn."] = "오스틸 드 몽은 브릴 여관 안에 있어요.",
    ["Ayanna Everstride is in a small room off the ramp that winds up Aldrassil."] = "아얀나 에버스트라이드는 알드랏실을 감아 오르는 경사로 옆 작은 방에 있어요.",
    ["Ayessa Dawnsinger is inside the lodge near the skycutter dock."] = "Ayessa Dawnsinger은(는) 하늘가르개 선착장 근처 오두막 안에 있어요.",
    ["Ayessa talks for about 75 seconds after you take this. Stay near her until it completes, then hand it in."] = "수락하면 Ayessa이(가) 약 75초 동안 말해요. 완료될 때까지 곁에 있다가 반납하세요.",
    ["Azar Stronghammer is upstairs in the distillery."] = "아자르 스트롱해머는 증류소 위층에 있어요.",
    ["Back up the slope beside the meeting stone to the hidden cave where Ebru and Nalpak stand."] = "만남의 돌 옆 비탈을 다시 올라가 에브루와 날팍이 있는 숨겨진 동굴로 가세요.",
    ["Badlands, Alterac Mountains and Swamp of Sorrows are nearly as good for this."] = "황야의 땅, 알터랙 산맥, 슬픔의 늪도 이 용도로 거의 비슷해요.",
    ["Badlands, Arathi Highlands and Alterac Mountains are nearly as good for this."] = "황야의 땅, 아라시 고원, 알터랙 산맥도 이 용도로 거의 비슷해요.",
    ["Badlands, Feralas and Stranglethorn Vale are nearly as good for this."] = "황야의 땅, 페랄라스, 가시덤불 골짜기도 이 용도로 거의 비슷해요.",
    ["Bael'dun Appraisers (level 8-9) heal themselves and wounded allies. Kill them first."] = "Bael'dun Appraiser(레벨 8-9)은(는) 자신과 다친 아군을 치유해요. 먼저 처치하세요.",
    ["Bailiff Conacher is inside the Lakeshire Town Hall."] = "집행관 코나처는 레이크샤이어 마을회관 안에 있어요.",
    ["Balance"] = "조화",
    ["Bandanas drop from the Defias inside the Deadmines too, so you can finish this during the run."] = "죽음의 폐광 안의 Defias도 두건을 드랍하니 던전을 돌면서 끝낼 수 있어요.",
    ["Barak Kodobane hits very hard, and the Kolkar Wrangler at his side nets you and shoots from range."] = "바라크 코도베인은 아주 세게 때리고, 곁의 콜카르일족 사냥꾼은 그물을 던지고 원거리에서 쏴요.",
    ["Bareth Dawnstone is on the top floor. Once you accept, stay with him until he's clear of the outpost."] = "Bareth Dawnstone은(는) 맨 위층에 있어요. 수락하면 전초기지를 벗어날 때까지 곁에 있으세요.",
    ["Bareth Dawnstone not here? Another player has taken this quest. Bareth Dawnstone is back a few minutes after they finish, so wait nearby."] = "Bareth Dawnstone이(가) 안 보이나요? 다른 플레이어가 이 퀘스트를 진행 중이에요. 퀘스트가 끝나고 몇 분 뒤에 돌아오니 근처에서 기다리세요.",
    ["Baron Anvillaxx, level 13, and level 12 Malevolent Storms attack during the fight with Lorthuna."] = "Lorthuna과(와) 싸우는 동안 Baron Anvillaxx(레벨 13)와(과) 레벨 12 Malevolent Storm이(가) 공격해요.",
    ["Baron Anvillaxx, level 13, and level 12 Malevolent Storms attack once Elaadrin starts the scene."] = "Elaadrin이(가) 장면을 시작하면 Baron Anvillaxx(레벨 13)와(과) 레벨 12 Malevolent Storm이(가) 공격해요.",
    ["Baron Longshore can be at any of the Southsea camps. Check each one."] = "남작 롱쇼어는 Southsea 야영지 중 어디에든 있을 수 있어요. 하나씩 확인하세요.",
    ["Baron Silverlaine"] = "남작 실버레인",
    ["Baros Alexston is inside the building at the edge of Cathedral Square."] = "바로스 알렉스턴은 Cathedral Square 가장자리 건물 안에 있어요.",
    ["Bartleby gives up at 1% health, so he won't fight to the death."] = "바틀비는 생명력 1%에서 항복해서 끝까지 싸우지 않아요.",
    ["Bartleby gives up at 1% health, so the fight ends there."] = "바틀비는 생명력 1%에서 항복해서 전투가 거기서 끝나요.",
    ["Bartleby yields at 1% health. Stop attacking and talk to him."] = "바틀비는 생명력 1%에서 항복해요. 공격을 멈추고 말을 거세요.",
    ["Bats silence you for about 10 seconds. Casters and healers stay back in the bat room."] = "박쥐가 약 10초 동안 침묵을 걸어요. 박쥐 방에서 시전자와 힐러는 뒤에 있으세요.",
    ["Battleboars (level 3-4) roam the hills round the shrine. Look for one near the fire before you click it."] = "전투멧돼지(레벨 3-4)가 성소 주변 언덕을 돌아다녀요. 클릭하기 전에 모닥불 근처를 살피세요.",
    ["Bazil Thredd"] = "바질 스레드",
    ["Bazil Thredd is elite: a hard fight alone."] = "바질 스레드는 정예: 혼자선 힘든 싸움이에요.",
    ["Bazzalan"] = "바잘란",
    ["Bear Tank"] = "곰 탱커",
    ["Bears, lions, murlocs and spiders above your level live along this walk. Keep to the arrow and pull nothing you can walk past."] = "이 길에는 내 레벨보다 높은 곰, 사자, 멀록, 거미가 살아요. 화살표를 따라가고, 지나칠 수 있는 몹은 풀링하지 마세요.",
    ["Beast Mastery"] = "야수",
    ["Belann Windwood is inside a house."] = "Belann Windwood은(는) 집 안에 있어요.",
    ["Belia Thundergranite is in the Hall of Arms, in the Military Ward."] = "빌리아 썬더그래니트는 Military Ward의 전투의 전당 안에 있어요.",
    ["Bellygrub (level 24) has far more health than a boar should, and uses Charge and Tremor, an area hit."] = "서리먹보(레벨 24)는 멧돼지치고 생명력이 훨씬 많고, 돌격과 광역 공격인 Tremor를 써요.",
    ["Bellygrub can be led back to Lakeshire, where the guards help. Do most of the damage yourself so the tusk drops."] = "서리먹보는 경비병이 돕는 레이크샤이어까지 끌고 갈 수 있어요. 엄니가 드랍되도록 피해는 대부분 직접 주세요.",
    ["Bellygrub has far more health than a normal boar. A very hard fight alone."] = "서리먹보는 보통 멧돼지보다 생명력이 훨씬 많아요. 혼자서는 아주 힘든 전투예요.",
    ["Belm keeps the inn inside the Thunderbrew Distillery."] = "Belm은(는) 썬더브루 양조장 안의 여관을 운영해요.",
    ["Benedict's Chest is upstairs, a floor above Benedict."] = "Benedict's Chest은(는) Benedict보다 한 층 위에 있어요.",
    ["Bennic and his bandits are level 7. Fight them one at a time in the cave."] = "레벨 7인 Bennic과(와) 산적들은 동굴에서 하나씩 상대하세요.",
    ["Benny Blaanco (level 15) is around the pumpkin farm and hits unusually hard. Fight him alone, at full health."] = "베니 블란코(레벨 15)는 호박 농장 주위에 있고 유난히 세게 때려요. 생명력을 가득 채우고 혼자 상대하세요.",
    ["Berard is a level 16 elite, and every villager around him is an elite too. Bring a group."] = "Berard은(는) 레벨 16 정예이고, 주변 마을 사람도 모두 정예예요. 파티를 데려가세요.",
    ["Besseleth webs you in place for 10 seconds, so you can't run once she has you. Go in at full health."] = "베스셀레스는 거미줄로 10초 동안 묶어서, 잡히면 도망칠 수 없어요. 생명력을 가득 채우고 들어가세요.",
    ["Big Bronze Bomb"] = "대형 청동 폭탄",
    ["Big Iron Bomb"] = "대형 철제 폭탄",
    ["Billibub Cogspinner in the Dwarven District sells Bronze Tubes. If he has none, try the Auction House."] = "Dwarven District의 빌리버브 코그스피너가 Bronze Tube를 팔아요. 없으면 경매장을 확인하세요.",
    ["Bind your hearth here. Sentinel Hill is your base until Redridge."] = "여기서 귀환석을 묶으세요. 붉은마루 산맥 전까지 감시의 언덕이 거점이에요.",
    ["Bingles' tools lie on the ground in the Stonesplinter trogg camp south-east of the dam."] = "Bingles의 공구는 댐 남동쪽 Stonesplinter 트로그 야영지 땅에 있어요.",
    ["Bjork"] = "비요크",
    ["Bjork patrols a long path. Clear the trash along it before you pull."] = "비요크는 긴 경로를 순찰해요. 풀링하기 전에 경로의 잡몹을 정리하세요.",
    ["Black Mageweave Gloves"] = "검은 마법매듭 장갑",
    ["Black Ravagers roam the road from Darkshire to Raven Hill and the woods toward the Yorgen Farmstead."] = "Black Ravager은(는) 다크샤이어에서 까마귀 언덕으로 가는 길과 요르겐 농장 쪽 숲을 돌아다녀요.",
    ["Blackfathom Deeps"] = "검은심연 나락",
    ["Blackmoss the Fetid is a rare and isn't always up. His heart starts this."] = "악취나는 검은이끼괴물은 희귀 몹이라 항상 있지 않아요. 그 심장으로 이 퀘스트가 시작돼요.",
    ["Blackmoss the Fetid is a rare level 13 Mire Beast and isn't always up. His Moss-twined Heart starts this quest. Skip him if he's too strong for you."] = "악취나는 검은이끼괴물은 레벨 13 희귀 Mire Beast라 항상 있지는 않아요. 그의 이끼로 덮인 심장으로 이 퀘스트를 시작해요. 너무 강하면 건너뛰세요.",
    ["Blackrock Outrunners cast Net, which roots you. Running from a bad pull is harder here."] = "Blackrock Outrunner은(는) 그물을 시전해 묶어요. 여기선 잘못 풀링하면 도망치기 더 어려워요.",
    ["Blackrock Outrunners throw Net and root you in place. Pull them one at a time."] = "Blackrock Outrunner은(는) 그물을 던져 묶어요. 하나씩 풀링하세요.",
    ["Blacksmithing 1-225"] = "대장기술 1-225",
    ["Blacksmithing lets you make Rough Sharpening Stones (blades) and Weightstones (blunt), +2 damage for 30 minutes."] = "대장기술로 조잡한 숫돌(날붙이)과 Weightstone(둔기)을 만들 수 있어요. 30분 동안 공격력 +2.",
    ["Blacksmiths: keep any Rough Stone you find in the mines. It makes sharpening stones and weightstones."] = "대장기술: 광산에서 찾은 작은 암석은 모두 챙기세요. 숫돌과 무게추 재료예요.",
    ["Blackwood Trackers (14-15) and Marosh the Devious (16) attack Aynasha in waves. Keep them off her."] = "Blackwood Tracker(14-15)와(과) 험상궂은 마로쉬(16)가 웨이브로 Aynasha를 공격해요. 그녀에게서 떼어 놓으세요.",
    ["Blackwood Ursas (18-19) and Shamans (19-20) hold Volcor's cave. Clear the ones by the mouth first."] = "Blackwood Ursa(18-19)와(과) Shaman(19-20)이(가) Volcor의 동굴을 지켜요. 입구 쪽부터 정리하세요.",
    ["Blademaster Ren stands inside the watchtower."] = "Blademaster Ren은(는) 감시탑 안에 있어요.",
    ["Blasted Lands is nearly as good for this."] = "저주받은 땅도 이 용도로 거의 비슷해요.",
    ["Blasted Lands, Burning Steppes and Searing Gorge are nearly as good for this."] = "저주받은 땅, 불타는 평원, 이글거리는 협곡도 이 용도로 거의 비슷해요.",
    ["Blind Mary is indoors."] = "눈 먼 매리는 실내에 있어요.",
    ["Bliztik is upstairs."] = "블리즈틱은 위층에 있어요.",
    ["Bliztik sells Healing Potions in small numbers. Buy any he has."] = "블리즈틱은 치유 물약을 조금만 팔아요. 있는 대로 사세요.",
    ["Bloodfeather Harpies along the Darnassus road drop the belts too, away from the Matriarchs."] = "Matriarch에게서 떨어진 다르나서스 길가의 Bloodfeather Harpy도 허리띠를 드랍해요.",
    ["Bloodfeather Matriarchs heal with Healing Wave and hit hard with Lightning Bolt. Kill them fast or leave them be."] = "Bloodfeather Matriarch은(는) 치유의 물결로 치유하고 번개 화살로 세게 때려요. 빨리 처치하거나 건드리지 마세요.",
    ["Bloodfury Ripper is elite, and attacking her pulls in harpies from far around."] = "혈폭풍일족 갈퀴발톱은 정예이고, 공격하면 멀리 있는 하피까지 몰려와요.",
    ["Bloodfury Slayers can execute you under 20% health, and Ambushers cast a hard shock often. Pull one at a time."] = "Bloodfury Slayer은(는) 생명력 20% 아래에서 마무리 일격을 하고, Ambusher은(는) 강한 충격을 자주 시전해요. 하나씩 풀링하세요.",
    ["Bloodhound Runts leave a disease that makes the tank take more damage. Cure it between pulls."] = "Bloodhound Runt는 탱커가 받는 피해를 늘리는 질병을 남겨요. 풀링 사이에 치료하세요.",
    ["Blow the Horn of Echeyakee at his lair to call him out."] = "그의 굴에서 에체야키의 뿔피리를 불어 그를 불러내세요.",
    ["Board the boat for Auberdine"] = "아우버다인행 배 탑승",
    ["Board the boat for Stormwind Harbor"] = "스톰윈드 항구행 배 탑승",
    ["Board the ship at Menethil Harbor's dock and sail to Southshore."] = "메네실 항구 부두에서 배를 타고 사우스쇼어로 가세요.",
    ["Boarton Shadetotem is stealthed. Walk right up to the arrow and he shows."] = "Boarton Shadetotem은(는) 은신 중이에요. 화살표까지 바로 걸어가면 나타나요.",
    ["Bolt of Linen Cloth"] = "리넨 두루마리",
    ["Bolt of Mageweave"] = "마법 두루마리",
    ["Bolt of Silk Cloth"] = "비단 두루마리",
    ["Bolt of Woolen Cloth"] = "양모 두루마리",
    ["Bombs come nonstop from Dark Iron Demolitionists at range. Close in fast or pull them out of sight."] = "Dark Iron Demolitionist이(가) 원거리에서 쉴 새 없이 폭탄을 던져요. 빨리 붙거나 시야 밖으로 끌어내세요.",
    ["Boosted Rest shows up after about a minute of sitting by Eric's fire."] = "Eric의 불 옆에 1분쯤 앉아 있으면 휴식 강화가 떠요.",
    ["Boss Copperplug, who drops the cover, is at the back of the Boulder Lode Mine."] = "덮개를 떨어뜨리는 사장 코퍼플러그는 돌무더기 광산 안쪽 끝에 있어요.",
    ["Both fight you at once: Lescovar is level 31, Marzon 30."] = "둘이 동시에 공격해요: Lescovar는 31레벨, Marzon은 30레벨이에요.",
    ["Both of Rahauro's quests can be shared. Someone in your group may already have them."] = "Rahauro의 퀘스트는 둘 다 공유할 수 있어요. 파티원이 이미 갖고 있을 수도 있어요.",
    ["Both tablets lie flat on the ground among the ruins."] = "석판 두 개 모두 폐허 사이 바닥에 놓여 있어요.",
    ["Bottles of Whispering Elixir lie about the Shadowvale crypt, some on the floor, some up on its walls."] = "Whispering Elixir 병은 어둠골짜기 묘실 곳곳에 있어요. 바닥에도, 벽 위에도 있어요.",
    ["Boulder Lode Mine mobs stand close enough to pull in pairs, and the tunnels leave little room to run."] = "돌무더기 광산 몹은 둘씩 끌릴 만큼 가까이 서 있고, 터널은 도망칠 공간이 거의 없어요.",
    ["Bounding Mana flies to one player and back. Anyone in its path takes about 300 and is silenced."] = "튕기는 마나는 한 플레이어에게 날아갔다 돌아와요. 경로에 있으면 약 300의 피해를 받고 침묵돼요.",
    ["Braldir Ashmantle is up a mountain trail south-west of Thelsamar."] = "Braldir Ashmantle은(는) 텔사마 남서쪽 산길 위에 있어요.",
    ["Branstock Khalder stands inside Anvilmar."] = "브란스토크 칼더는 앤빌마 안에 서 있어요.",
    ["Brave Moonhorn stands at the top of the Great Lift, on the Barrens side."] = "용사 문혼은 구름 승강장 꼭대기, 불모의 땅 쪽에 서 있어요.",
    ["Brave Wildrunner walks a short patrol in Bloodhoof Village."] = "용사 와일드러너는 블러드후프 마을에서 짧게 순찰해요.",
    ["Brave Wildrunner walks a short round right beside Baine Bloodhoof."] = "용사 와일드러너는 바인 블러드후프 바로 옆을 짧게 돌아요.",
    ["Brave Windfeather walks a short round through the camp, so look around if she isn't at the arrow."] = "용사 윈드페더는 야영지를 짧게 돌아서, 화살표 위치에 없으면 주변을 둘러보세요.",
    ["Break line of sight to stop his Shadow Bolts."] = "시야를 끊어 그의 어둠의 화살을 멈추세요.",
    ["Briarthorn (skill 70), Bruiseweed (skill 100), Wild Steelbloom (skill 115), Kingsblood (skill 125), Stranglekelp (skill 85). About 16 nodes on a 10-spot loop."] = "브라이어쏜 (숙련도 70), 생채기풀 (숙련도 100), 야생 철쭉 (숙련도 115), 왕꽃잎풀 (숙련도 125), 갈래물풀 (숙련도 85). 10곳을 도는 순환로에서 채집물 약 16개.",
    ["Briarthorn (skill 70), Mageroyal (skill 50), Earthroot (skill 15), Silverleaf (skill 1), Peacebloom (skill 1), Stranglekelp (skill 85). About 26 nodes on a 10-spot loop."] = "브라이어쏜 (숙련도 70), 마법초 꽃잎 (숙련도 50), 뱀뿌리 (숙련도 15), 은엽수잎 (숙련도 1), 평온초 (숙련도 1), 갈래물풀 (숙련도 85). 10곳을 도는 순환로에서 채집물 약 26개.",
    ["Briarthorn (skill 70), Mageroyal (skill 50), Silverleaf (skill 1), Peacebloom (skill 1), Earthroot (skill 15). About 10 nodes on a 10-spot loop."] = "브라이어쏜 (숙련도 70), 마법초 꽃잎 (숙련도 50), 은엽수잎 (숙련도 1), 평온초 (숙련도 1), 뱀뿌리 (숙련도 15). 10곳을 도는 순환로에서 채집물 약 10개.",
    ["Briarthorn, Bruiseweed, Wild Steelbloom"] = "브라이어쏜, 생채기풀, 야생 철쭉",
    ["Briarthorn, Mageroyal, Earthroot"] = "브라이어쏜, 마법초 꽃잎, 뱀뿌리",
    ["Briarthorn, Mageroyal, Silverleaf"] = "브라이어쏜, 마법초 꽃잎, 은엽수잎",
    ["Brilliant Smallfish"] = "비단잉어 구이",
    ["Brine is in her hut, up above the watering hole."] = "브린은 물웅덩이 위쪽 자기 오두막에 있어요.",
    ["Bring 10 Linen Cloth, from humanoids such as the Defias, and you hand this in on the spot."] = "Defias 같은 인간형에게서 얻는 리넨 옷감 10개를 가져오면 그 자리에서 반납돼요.",
    ["Bring 3 Silk Cloth. Humanoids drop it, and the Auction House in the Trade District sells it."] = "비단 옷감 3개를 가져가세요. 인간형 몹이 드랍하고, Trade District 경매장에서도 팔아요.",
    ["Bring a healing potion. This fight often ends up needing one."] = "치유 물약을 챙기세요. 이 싸움은 자주 물약이 필요해져요.",
    ["Bring a poison cure. Each hit on him stacks a debuff that lowers your physical damage."] = "독 해제를 준비하세요. 그를 때릴 때마다 물리 피해를 낮추는 디버프가 쌓여요.",
    ["Bring cures. Raptors cause bleeds, spiders poison you, and crocs and spiders spread diseases."] = "해제 수단을 챙기세요. 랩터는 출혈, 거미는 독, 악어와 거미는 질병을 걸어요.",
    ["Bristle Whisker Catfish"] = "표범메기 구이",
    ["Bristleback Geomancers are level 19-20, the toughest here. Take them one at a time."] = "Bristleback Geomancer은(는) 레벨 19-20로 여기서 가장 강해요. 하나씩 상대하세요.",
    ["Brock Stoneseeker is usually downstairs inside his building, though he sometimes stands outside it."] = "브록 스톤시커는 보통 자기 건물 아래층 안에 있지만, 가끔 밖에 서 있어요.",
    ["Brog also sells the Small Brown Pouch if you need bag space."] = "가방 공간이 필요하면 Brog에게서 작은 갈색 가방도 살 수 있어요.",
    ["Bromos Grummner stands just inside Anvilmar's door."] = "브로모스 그럼너는 앤빌마 문 바로 안쪽에 서 있어요.",
    ["Brontus, a level 27 elite kodo, roams here and drops the liver too. Take it from the plain kodos."] = "레벨 27 정예 코도 브론투스도 여기를 돌아다니며 간을 떨어뜨려요. 간은 일반 코도에게서 얻으세요.",
    ["Bronze Framework"] = "청동 골격",
    ["Bronze Warhammer"] = "청동 전투해머",
    ["Brother Kristoff stands outside the Cathedral of Light, in Cathedral Square."] = "수사 크리스토프는 Cathedral Square, Cathedral of Light 밖에 서 있어요.",
    ["Brother Neals is on the abbey's upper floor."] = "수사 닐스는 수도원 위층에 있어요.",
    ["Brother Paxton is in Northshire Abbey's library, on the ground floor."] = "수사 팩스턴은 노스샤이어 수도원 도서관 1층에 있어요.",
    ["Brother Paxton is indoors, in the abbey's library."] = "수사 팩스턴은 실내, 수도원 도서관에 있어요.",
    ["Brother Paxton is indoors, in the abbey."] = "수사 팩스턴은 실내, 수도원 안에 있어요.",
    ["Brother Paxton is inside Northshire Abbey."] = "수사 팩스턴은 노스샤이어 수도원 안에 있어요.",
    ["Brother Sammuel is on the abbey's ground floor, next to Llane Beshere."] = "수사 사무엘은 수도원 1층, 레인 비셰어 옆에 있어요.",
    ["Brother Sarno is inside the Cathedral of Light."] = "수사 세르노는 Cathedral of Light 안에 있어요.",
    ["Brown Linen Vest"] = "갈색 리넨 조끼",
    ["Bruegs Kindleborn is in a cave high on the mountain above the South Gate Pass."] = "Bruegs Kindleborn은(는) 남부 관문 통행로 위 산 높은 곳 동굴에 있어요.",
    ["Bruegs Kindleborn is in a cave near the top of the mountain by South Gate Pass. A trail climbs to it."] = "Bruegs Kindleborn은(는) 남부 관문 통행로 옆 산꼭대기 근처 동굴에 있어요. 산길이 거기까지 올라가요.",
    ["Bruegs's cave sits high above the pass. Take the trail down; jumping off the ledge means fall damage."] = "Bruegs의 동굴은 고개 위 높은 곳에 있어요. 산길로 내려가세요. 절벽에서 뛰면 낙하 피해를 입어요.",
    ["Bruiseweed (skill 100), Briarthorn (skill 70), Mageroyal (skill 50), Peacebloom (skill 1), Earthroot (skill 15). About 78 nodes on a 10-spot loop."] = "생채기풀 (숙련도 100), 브라이어쏜 (숙련도 70), 마법초 꽃잎 (숙련도 50), 평온초 (숙련도 1), 뱀뿌리 (숙련도 15). 10곳을 도는 순환로에서 채집물 약 78개.",
    ["Bruiseweed (skill 100), Briarthorn (skill 70), Mageroyal (skill 50), Stranglekelp (skill 85), Wild Steelbloom (skill 115), Peacebloom (skill 1). About 148 nodes on a 10-spot loop."] = "생채기풀 (숙련도 100), 브라이어쏜 (숙련도 70), 마법초 꽃잎 (숙련도 50), 갈래물풀 (숙련도 85), 야생 철쭉 (숙련도 115), 평온초 (숙련도 1). 10곳을 도는 순환로에서 채집물 약 148개.",
    ["Bruiseweed (skill 100), Kingsblood (skill 125), Wild Steelbloom (skill 115), Stranglekelp (skill 85), Grave Moss (skill 120), Briarthorn (skill 70). About 18 nodes on a 10-spot loop."] = "생채기풀 (숙련도 100), 왕꽃잎풀 (숙련도 125), 야생 철쭉 (숙련도 115), 갈래물풀 (숙련도 85), 무덤이끼 (숙련도 120), 브라이어쏜 (숙련도 70). 10곳을 도는 순환로에서 채집물 약 18개.",
    ["Bruiseweed (skill 100), Mageroyal (skill 50), Briarthorn (skill 70). About 36 nodes on a 10-spot loop."] = "생채기풀 (숙련도 100), 마법초 꽃잎 (숙련도 50), 브라이어쏜 (숙련도 70). 10곳을 도는 순환로에서 채집물 약 36개.",
    ["Bruiseweed (skill 100), Stranglekelp (skill 85), Wild Steelbloom (skill 115), Briarthorn (skill 70), Mageroyal (skill 50). About 5 nodes on a 10-spot loop."] = "생채기풀 (숙련도 100), 갈래물풀 (숙련도 85), 야생 철쭉 (숙련도 115), 브라이어쏜 (숙련도 70), 마법초 꽃잎 (숙련도 50). 10곳을 도는 순환로에서 채집물 약 5개.",
    ["Bruiseweed, Briarthorn, Mageroyal"] = "생채기풀, 브라이어쏜, 마법초 꽃잎",
    ["Bruiseweed, Kingsblood, Wild Steelbloom"] = "생채기풀, 왕꽃잎풀, 야생 철쭉",
    ["Bruiseweed, Mageroyal, Briarthorn"] = "생채기풀, 마법초 꽃잎, 브라이어쏜",
    ["Bruiseweed, Stranglekelp, Wild Steelbloom"] = "생채기풀, 갈래물풀, 야생 철쭉",
    ["Bruuz is a level 20 elite in the water off Ratchet, hard for one player."] = "Bruuz은(는) 톱니항 앞바다의 레벨 20 정예로, 혼자서는 어려워요.",
    ["Buff Guard Roberts with Power Word: Fortitude and heal him with the Rank 2 Lesser Heal."] = "경비병 로버트에게 신의 권능: 인내를 걸고 2 레벨 하급 치유로 치유하세요.",
    ["Burning Blade at 10 to 12 crowd the trail and the den. Pull them singly on the way up."] = "레벨 10~12 불타는 칼날단이 길과 굴에 몰려 있어요. 올라가며 하나씩 풀링하세요.",
    ["Bury Samuel's Remains at Marla's Grave, front row of the Deathknell graveyard, north of the church."] = "교회 북쪽 데스넬 묘지 앞줄, Marla's Grave에서 사무엘의 유골 묻기.",
    ["Buy a Raw Brilliant Smallfish at the Auction House, or catch one in the pond north of Boarton."] = "경매장에서 비단잉어를 사거나 Boarton 북쪽 연못에서 낚으세요.",
    ["Buy a Shiny Bauble and 3 Nightcrawlers from Catherine Leland on your way to the harbor."] = "항구로 가는 길에 캐서린 리랜드에게서 반짝이는 미끼 하나와 큰지렁이 3개를 사세요.",
    ["Buy a Thunder Ale from Innkeeper Belm first. Giving it to Jarven distracts him."] = "먼저 여관주인 벨름에게서 썬더 에일 맥주를 사세요. Jarven에게 주면 한눈을 팔아요.",
    ["Buy the Balanced Throwing Dagger here. It does three times the damage of your Small Throwing Knife."] = "여기서 소형 투척용 단검을 사세요. 소형 투척용 나이프보다 피해가 세 배예요.",
    ["Buy the Wise Man's Belt here, about 14 silver. You can wear it from level 15."] = "여기서 현인의 허리띠를 사세요. 약 14실버, 레벨 15부터 착용할 수 있어요.",
    ["Buzzbox 323 sits at the top of a ramp."] = "버즈박스 323은 경사로 꼭대기에 있어요.",
    ["Buzzbox 411 sits on the ground. Look down when the arrow lands."] = "버즈박스 411은 땅에 놓여 있어요. 화살표가 도착하면 아래를 보세요.",
    ["Buzzbox 827 sits on the ground, just south of the flight platform."] = "버즈박스 827은 비행 발판 바로 남쪽 땅에 놓여 있어요.",
    ["By the dead tree, use the Fresh Zhevra Carcass. Ishamuhale comes out to eat it."] = "죽은 나무 옆에서 방금 죽은 얼룩말 시체를 사용하세요. 이샤무헤일이 먹으러 나와요.",
    ["Cain Firesong is upstairs in the Brill inn."] = "케인 파이어송은 브릴 여관 위층에 있어요.",
    ["Cain Firesong teaches from the Brill inn's upper floor."] = "케인 파이어송은 브릴 여관 위층에서 가르쳐요.",
    ["Camp Narache"] = "나라체 야영지",
    ["Camp Taurajo, The Barrens"] = "타우라조 야영지 (불모의 땅)",
    ["Campfires can't be lit in Ironforge or below it. Get your camp buffs outside the city before you go."] = "아이언포지 안이나 그 아래에서는 모닥불을 피울 수 없어요. 들어가기 전에 도시 밖에서 야영 버프를 받으세요.",
    ["Camping 101: Alchemy, from the adventurer near your first town: at skill 20 your trainer teaches you the Mana Well, a camp feature for your campfire."] = "캠핑 입문: 연금술: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 모닥불용 야영지 시설인 마나 우물을 가르쳐 줘요.",
    ["Camping 101: Blacksmithing, from the adventurer near your first town: at skill 20 your trainer teaches you the Sharpening Wheel, a camp feature for your campfire."] = "캠핑 입문: 대장기술: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 모닥불용 야영지 시설인 연마 바퀴를 가르쳐 줘요.",
    ["Camping 101: Cooking, from the adventurer near your first town, brings you to your first cook."] = "캠핑 입문: 요리: 첫 마을 근처 모험가에게서 받아요. 첫 요리 전문가에게 안내해 줘요.",
    ["Camping 101: Enchanting, from the adventurer near your first town: at skill 20 your trainer teaches you the Enchanted Lute, a camp feature for your campfire."] = "캠핑 입문: 마법부여: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 모닥불용 야영지 시설인 마력 깃든 류트를 가르쳐 줘요.",
    ["Camping 101: Engineering, from the adventurer near your first town: at skill 20 your trainer teaches you the Reagent Bot, a camp feature. It needs a Copper Tube: make it once you can."] = "캠핑 입문: 기계공학: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 야영지 시설인 재료 로봇을 가르쳐 줘요. 구리관이 필요하니 만들 수 있게 되면 만드세요.",
    ["Camping 101: First Aid, from the adventurer near your first town: at skill 20 your trainer teaches you the First Aid Kit, a camp feature for your campfire."] = "캠핑 입문: 응급치료: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 모닥불용 야영지 시설인 응급치료 도구를 가르쳐 줘요.",
    ["Camping 101: Fishing, from the adventurer near your first town: the trainer teaches you the Fish Bowl, a camp feature that raises the stats of everyone sitting by your campfire."] = "캠핑 입문: 낚시: 첫 마을 근처 모험가에게서 받아요. 전문가가 생선 그릇을 가르쳐 줘요. 모닥불 곁에 앉은 모두의 능력치를 올려 주는 야영지 시설이에요.",
    ["Camping 101: Herbalism, from the adventurer near your first town: at skill 20 your trainer teaches you the Incense Candle, a camp feature for your campfire."] = "캠핑 입문: 약초채집: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 모닥불용 야영지 시설인 향기 나는 양초를 가르쳐 줘요.",
    ["Camping 101: Leatherworking, from the adventurer near your first town: at skill 20 your trainer teaches you the Camp Tent, a camp feature for your campfire."] = "캠핑 입문: 가죽세공: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 모닥불용 야영지 시설인 캠핑 텐트를 가르쳐 줘요.",
    ["Camping 101: Mining, from the adventurer near your first town: at skill 20 your trainer teaches you the Lodestone, a camp feature for your campfire (1 Rough Stone and 1 Copper Bar)."] = "캠핑 입문: 채광: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 모닥불용 야영지 시설인 자철석을 가르쳐 줘요(작은 암석 1개, 구리 주괴 1개).",
    ["Camping 101: Skinning, from the adventurer near your first town: at skill 20 your trainer teaches you the Camp Chair, a camp feature for your campfire."] = "캠핑 입문: 무두질: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 모닥불용 야영지 시설인 캠핑 의자를 가르쳐 줘요.",
    ["Camping 101: Tailoring, from the adventurer near your first town: at skill 20 your trainer teaches you the Faction Banner, a camp feature for your campfire."] = "캠핑 입문: 재봉술: 첫 마을 근처 모험가에게서 받아요. 숙련도 20에 담당 전문가가 모닥불용 야영지 시설인 진영 깃발을 가르쳐 줘요.",
    ["Can't find it? Enchant Cloak - Greater Defense also works from skill 221 to 225, at a higher cost."] = "못 찾겠나요? 숙련도 221-225에서는 망토 마법부여 - 상급 보호도 되지만 비용이 더 들어요.",
    ["Captain Dargol, level 13, waits on the crypt's lowest level. Clear the Ancestors in his room first."] = "레벨 13 대장 다르골은 지하 묘지 맨 아래층에서 기다려요. 먼저 방의 Ancestor를 정리하세요.",
    ["Captain Gerogg Hammertoe, a rare level 27 elite, can be up inside Bael'dun Keep. Check before each pull."] = "레벨 27 희귀 정예 경비대장 지로그 해머토가 바엘던 요새 안에 있을 수 있어요. 풀링할 때마다 확인하세요.",
    ["Captain Greenskin"] = "선장 그린스킨",
    ["Captain Melrache and his bodyguards are inside the tower."] = "대장 멜라케와 그의 호위병들은 탑 안에 있어요.",
    ["Captain Rugelfuss is upstairs, at the very top of the southern guard tower."] = "경비대장 루겔퍼스는 위층, 남쪽 경비탑 맨 꼭대기에 있어요.",
    ["Captain Sanders' chest sits on the small island off the coast. Swim out to it."] = "Captain Sanders의 상자는 해안 앞 작은 섬에 있어요. 헤엄쳐 가세요.",
    ["Captain Stoutfist is on the top floor of Menethil Keep, up the stairs."] = "경비대장 스타우트피스트는 계단 위, 메네실 요새 꼭대기 층에 있어요.",
    ["Captain Truman stands where you zone in, in the north-east corner."] = "Captain Truman은 들어오는 곳, 북동쪽 구석에 있어요.",
    ["Captain Vachon is inside the Scarlet tower."] = "대장 바콘은 Scarlet 탑 안에 있어요.",
    ["Carendin Halgar is in the Magic Quarter."] = "카렌딘 할가르는 Magic Quarter에 있어요.",
    ["Carry 10 Linen Cloth here and this hands in on the spot. Troggs and other humanoids drop it."] = "리넨 옷감 10개를 가져오면 그 자리에서 반납돼요. 트로그와 다른 인간형이 드랍해요.",
    ["Carry the Shrine Bauble to the tree at the Shrine of Remulos and use it from your bags."] = "제단 구슬을 레물로스의 제단의 나무로 가져가 가방에서 사용하세요.",
    ["Cast Holy Light on 5 Injured Deathguards, found just north of Deathknell among the zombies."] = "데스넬 바로 북쪽 좀비들 사이에 있는 Injured Deathguard 5명에게 성스러운 빛을 시전하세요.",
    ["Cast Read Leyline at the standing stones"] = "선돌에서 지맥 읽기 시전",
    ["Cast Skysight at the Elemental Convergence"] = "정기의 합일에서 창공안 시전",
    ["Cast Teleport: Moonglade"] = "순간이동: 달의 숲 시전",
    ["Cast Teleport: Moonglade for the way back to Dendrite. It lands you much closer than the walk north."] = "Dendrite로 돌아갈 때 순간이동: 달의 숲을 시전하세요. 북쪽으로 걷는 것보다 훨씬 가까이 내려 줘요.",
    ["Cast the Taming Rod from as far away as it reaches, so the cast ends before the beast gets to you."] = "조련용 막대를 닿는 최대 거리에서 시전하세요. 그래야 야수가 오기 전에 시전이 끝나요.",
    ["Casters stay 10 yards away. His Dust Storm makes nearby attacks miss."] = "주문시전자는 10미터 떨어져 있으세요. 그의 먼지 폭풍은 근처 공격을 빗나가게 해요.",
    ["Casters: any Felmusk satyr can silence you for 6 seconds, instantly (Overwhelming Stench). Heal early."] = "주문시전자: Felmusk 사티로스는 누구나 즉시 6초 침묵을 걸 수 있어요(지독한 냄새). 미리 치유하세요.",
    ["Catseye Draught"] = "고양이눈 약물",
    ["Cerellean Whiteclaw stands out on the dock."] = "셀렐리안 화이트클로는 부두에 서 있어요.",
    ["Chain Bolt jumps between up to three players for heavy damage. Spread out and interrupt it."] = "연쇄 벼락은 최대 세 플레이어 사이를 튀며 큰 피해를 줘요. 흩어지고 차단하세요.",
    ["Charlga Razorflank"] = "서슬깃 차를가",
    ["Chatter, a level 23 rare spider, roams Alther's Mill among the Greater Tarantulas."] = "레벨 23 희귀 거미 우두머리 집게턱타란툴라가 거대한 타란툴라 사이로 앨더의 제재소를 돌아다녀요.",
    ["Check Dawn Brightstar's limited stock of scrolls and potions while you're here."] = "여기 온 김에 Dawn Brightstar의 한정 두루마리와 물약을 확인하세요.",
    ["Check the Heavy Recurve Bow here against the bow you're using."] = "여기 강화 곡궁을 지금 쓰는 활과 비교하세요.",
    ["Chef Breanna is inside the house just west of the inn."] = "주방장 브리나는 여관 바로 서쪽 집 안에 있어요.",
    ["Chef Grual only offers this at Cooking 50."] = "주방장 그루얼은 요리 50이 돼야 이 퀘스트를 줘요.",
    ["Chef Grual works in the inn's kitchen."] = "주방장 그루얼은 여관 주방에서 일해요.",
    ["Chief Hawkwind is inside his hut, a short walk north-west of Grull."] = "족장 호크윈드는 Grull에서 북서쪽으로 조금 걸으면 나오는 자기 오두막 안에 있어요.",
    ["Chief Sharptusk Thornmantle waits inside the biggest hut of the Bristleback camp."] = "족장 뾰족어금니는 Bristleback 야영지에서 가장 큰 오두막 안에서 기다려요.",
    ["Chol'aruk is built for a group of five. Don't take him on alone."] = "Chol'aruk은(는) 5인 파티용이에요. 혼자 상대하지 마세요.",
    ["Chol'aruk is inside a cave in the Razormane hills east of the Crossroads."] = "Chol'aruk은(는) 크로스로드 동쪽 Razormane 언덕의 동굴 안에 있어요.",
    ["Christopher Hewen at Sentinel Hill sells both too."] = "감시의 언덕의 크리스토퍼 히웬도 둘 다 팔아요.",
    ["Cirrusfly Soldiers swarm around the queen. Clear the nearest ones before you pull her."] = "Cirrusfly Soldier가 여왕 주위에 몰려 있어요. 여왕을 풀링하기 전에 가까운 것부터 정리하세요.",
    ["City of Dalaran"] = "달라란",
    ["Clara's Fresh Apples sit on a table inside her farm house, north-west of Goldshire in Elwynn Forest."] = "Clara's Fresh Apples은(는) 엘윈 숲의 골드샤이어 북서쪽, Clara의 농가 안 탁자 위에 있어요.",
    ["Clarice Foster is down in the Pools of Vision, under the Spirit Rise."] = "클라리스 포스터는 정기의 봉우리 아래 예언의 웅덩이에 있어요.",
    ["Clear a corner, pull him there and keep your backs to the wall."] = "구석 하나를 정리하고 그를 거기로 끌어 벽을 등지고 싸우세요.",
    ["Clear a way out first. Running out resets the Voidwalkers and the Succubus."] = "먼저 빠져나갈 길을 정리하세요. 밖으로 뛰어나가면 공허방랑자와 서큐버스가 초기화돼요.",
    ["Clear every pack around him first, then kill him as fast as you can."] = "주위의 무리를 모두 먼저 정리한 뒤 최대한 빨리 처치하세요.",
    ["Clear his room before you wake him. He puts a player to sleep, often the tank, and Mind Blasts."] = "깨우기 전에 방을 정리하세요. 한 명(주로 탱커)을 재우고 Mind Blast를 써요.",
    ["Clear one side of the room, let his patrol bring him close, then pull him alone."] = "방 한쪽을 정리하고 그가 순찰하며 다가올 때 혼자 풀링하세요.",
    ["Clear the Grimtotems around the fire before you light it. Lighting it brings out Arikara."] = "불을 붙이기 전에 모닥불 주위 Grimtotem을 정리하세요. 불을 붙이면 아리카라가 나와요.",
    ["Clear the Sentries on the chest's floor first. After you loot the journal you can't Stealth for a while."] = "상자가 있는 층의 Sentry를 먼저 정리하세요. 일지를 루팅하면 한동안 은신할 수 없어요.",
    ["Clear the alley first, then pull. Kill the two spiders before Witherfang."] = "골목을 먼저 정리하고 풀링하세요. 쇠퇴송곳니 전에 거미 둘을 처치하세요.",
    ["Clear the crocs near his path, then pull him in the open."] = "그의 경로 근처 악어를 정리한 뒤 트인 곳에서 풀링하세요.",
    ["Clear the enemies around the statue first, and have full mana for the waves."] = "석상 주위 적을 먼저 정리하고, 웨이브에 대비해 마나를 가득 채우세요.",
    ["Clear the ghoul packs before him one at a time. They stand close together."] = "그 앞의 구울 무리를 하나씩 정리하세요. 서로 가까이 서 있어요.",
    ["Clear the mobs around him first. Interrupt his Healing Touch, which heals him for a lot."] = "주위 몹을 먼저 정리하세요. 크게 회복하는 그의 치유의 손길을 끊으세요.",
    ["Clear the mobs standing in front of the barn before you go in."] = "들어가기 전에 헛간 앞에 선 몹을 정리하세요.",
    ["Clear the murlocs around the camp first, staying well away from the bonfire."] = "모닥불에서 멀리 떨어진 채 야영지 주위 멀록부터 정리하세요.",
    ["Clear the spiders around Besseleth first, or they join her fight."] = "베스셀레스 주위 거미를 먼저 정리하세요. 아니면 싸움에 끼어들어요.",
    ["Clerk Daltry is inside the Darkshire Town Hall."] = "서기관 달트리는 다크샤이어 마을회관 안에 있어요.",
    ["Click Kuramaa's Stump, then kill Kuramaa and loot his mask"] = "Kuramaa's Stump를 클릭한 다음, Kuramaa를 처치하고 가면을 루팅",
    ["Click the Archival Panel at his right to wake him, once everyone is ready."] = "모두 준비되면 그의 오른쪽 Archival Panel을 클릭해 깨우세요.",
    ["Click the Beached Sea Creature at its neck end."] = "떠내려온 바다 생물의 목 쪽 끝을 클릭하세요.",
    ["Click the Dead Cultist"] = "Dead Cultist 클릭",
    ["Click the Great Cat Spirit Statue at the den's mouth for stealth, then go in. The relics are deep inside."] = "굴 입구의 거대한 살쾡이의 혼 Statue을(를) 클릭해 은신한 다음 들어가세요. 유물은 깊숙한 안쪽에 있어요.",
    ["Click the Ritual Fire at the shrine of An'she and Mu'sha"] = "An'she와 Mu'sha의 제단에서 Ritual Fire 클릭",
    ["Click the Skyborne Portal next to Denaaris. It takes you to Stormwind."] = "Denaaris 옆의 Skyborne Portal을 클릭하세요. 스톰윈드로 이동해요.",
    ["Click the Wardrobe upstairs in Falaath Village"] = "팔라스 마을 위층의 Wardrobe 클릭",
    ["Click the hurt druids in the Nightfang Den to heal them"] = "Nightfang Den의 다친 드루이드를 클릭해 치유",
    ["Click the six green Kobold Tracks along the road to Goldshire"] = "골드샤이어로 가는 길의 녹색 Kobold Tracks 6개 클릭",
    ["Click the skull by the Brill mausoleum to call Ulag the Cleaver, then kill him."] = "브릴 묘실 옆 해골을 클릭해 학살자 울라그를 부른 다음 처치하세요.",
    ["Climb to the Venture Co. platform from the east side of Windshear Crag."] = "칼바람 바위산 동쪽에서 Venture Co. 발판으로 올라가세요.",
    ["Clyde Kellen fishes at Brightwater Lake, east of Brill."] = "클리데 켈렌은 브릴 동쪽 청명 호수에서 낚시해요.",
    ["Coarse Blasting Powder"] = "굵은 화약",
    ["Coarse Dynamite"] = "일반 다이너마이트",
    ["Coarse Grinding Stone"] = "일반 연마석",
    ["Coldridge Valley and Dun Morogh"] = "눈마루 골짜기와 던 모로",
    ["Coleman Farthing is inside the Brill inn."] = "콜만 파딩은 브릴 여관 안에 있어요.",
    ["Collecting Memories and Oh Brother are both finished in the mine before the Deadmines portal."] = "기억을 더듬어...와(과) Oh Brother는 둘 다 죽음의 폐광 차원문 전에 광산에서 끝내요.",
    ["Collin Mauren in Stormwind takes the crystals. Hand them in on your next visit there."] = "스톰윈드의 콜린 마우렌이 수정을 받아요. 다음에 스톰윈드에 갈 때 완료하세요.",
    ["Combat"] = "전투",
    ["Combust is magic, so it can be dispelled."] = "연소는 마법이라 해제할 수 있어요.",
    ["Come back down the same trail you climbed."] = "올라온 산길로 다시 내려가세요.",
    ["Commander Belguilos is indoors, one floor up in a house."] = "사령관 벨길로스는 집 안 한 층 위에 있어요.",
    ["Commander Springvale"] = "사령관 스프링베일",
    ["Complete the following dungeons."] = "다음 던전을 완료하세요.",
    ["Cook Charred Wolf Meat while you wait. It raises Cooking and leaves your Small Eggs alone."] = "기다리는 동안 늑대 숯불구이를 요리하세요. 요리 숙련도가 오르고 Small Egg는 남아요.",
    ["Cooked Crab Claw"] = "집게발 요리",
    ["Cookie"] = "쿠키",
    ["Cooking 1-225"] = "요리 1-225",
    ["Cooks: Small Spider Legs make Kaldorei Spider Kabobs and Small Eggs make Herb Baked Eggs, both early skill-ups."] = "요리: Small Spider Leg로 Kaldorei Spider Kabob, Small Egg로 Herb Baked Egg를 만들어요. 둘 다 초반 숙련도용이에요.",
    ["Cooks: the dire wolves here drop Lean Wolf Flanks for Seasoned Wolf Kabobs. Keep them."] = "요리사: 여기 큰늑대가 늑대 양념 케밥용 Lean Wolf Flank를 드랍해요. 챙기세요.",
    ["Cooks: these wolves drop Lean Wolf Flanks for Seasoned Wolf Kabobs. Keep them."] = "요리: 이 늑대들은 늑대 양념 케밥에 쓰는 Lean Wolf Flank를 드랍해요. 챙기세요.",
    ["Copper Chain Belt"] = "구리 사슬 허리띠",
    ["Copper Modulator"] = "구리 변조기",
    ["Copper Tube"] = "구리관",
    ["Copper Vein"] = "구리 광맥",
    ["Copper Vein (skill 1), Poor Copper Vein (skill 1, new in Forever). About 79 nodes on a 10-spot loop."] = "Copper Vein(숙련도 1), Poor Copper Vein(숙련도 1, Forever 신규). 10곳 순환 경로에 약 79개.",
    ["Copper Vein (skill 1), Poor Copper Vein (skill 1, new in Forever). About 99 nodes on a 10-spot loop."] = "Copper Vein(숙련도 1), Poor Copper Vein(숙련도 1, Forever 신규). 10곳 순환 경로에 약 99개.",
    ["Copper Vein (skill 1), Tin Vein (skill 65), Silver Vein (skill 75). About 83 nodes on a 10-spot loop."] = "Copper Vein(숙련도 1), Tin Vein(숙련도 65), Silver Vein(숙련도 75). 10곳을 도는 순환로에서 광맥 약 83개.",
    ["Copper Vein (skill 1). About 99 nodes on a 10-spot loop."] = "Copper Vein(숙련도 1). 10곳을 도는 순환로에서 광맥 약 99개.",
    ["Copper Vein, Poor Copper Vein"] = "구리 광맥, Poor Copper Vein",
    ["Copper Vein, Tin Vein, Silver Vein"] = "구리 광맥, 주석 광맥, 은 광맥",
    ["Coriella Calmbreeze runs the village inn."] = "Coriella Calmbreeze이(가) 마을 여관을 운영해요.",
    ["Cornelius is dead. Look for his body inside the den."] = "Cornelius은(는) 죽었어요. 굴 안에서 시체를 찾으세요.",
    ["Corporal Keeshan not here? Another player has taken this quest. Corporal Keeshan is back about 1 min after they finish, so wait nearby. If someone is about to take it, group up first: the game offers it to the whole group."] = "하사관 키샨이 안 보이나요? 다른 플레이어가 이 퀘스트를 진행 중이에요. 퀘스트가 끝나고 약 1분 뒤에 하사관 키샨이 돌아오니 근처에서 기다리세요. 누가 곧 받으려 하면 먼저 파티를 맺으세요. 파티원 모두에게 퀘스트가 공유돼요.",
    ["Corporal Keeshan waits at the far end of the Render's Rock cave."] = "하사관 키샨은 약탈의 바위굴 동굴 맨 끝에서 기다려요.",
    ["Counts toward the Legacy challenge Experienced Spelunker."] = "Legacy 도전 과제 숙련된 동굴탐험가에 포함돼요.",
    ["Counts toward the Legacy challenge Novice Spelunker (either one counts)."] = "Legacy 도전 과제 수습 동굴탐험가에 포함돼요(둘 중 하나면 돼요).",
    ["Counts toward the Legacy challenge Novice Spelunker."] = "Legacy 도전 과제 수습 동굴탐험가에 포함돼요.",
    ["Coyote (LvL. 10), Coyote Packleader (LvL. 12). About 140 skins on a 8-spot loop."] = "코요테 (LvL. 10), 우두머리 코요테 (LvL. 12). 8곳을 도는 순환로에서 가죽 약 140개.",
    ["Coyote Packleader (LvL. 12), Coyote (LvL. 10). About 42 skins on a 8-spot loop."] = "우두머리 코요테 (LvL. 12), 코요테 (LvL. 10). 8곳을 도는 순환로에서 가죽 약 42개.",
    ["Coyote Packleader (LvL. 12), Coyote (LvL. 10). About 54 skins on a 8-spot loop."] = "우두머리 코요테 (LvL. 12), 코요테 (LvL. 10). 8곳을 도는 순환로에서 가죽 약 54개.",
    ["Coyote Packleader, Coyote"] = "우두머리 코요테, 코요테",
    ["Coyote, Coyote Packleader"] = "코요테, 우두머리 코요테",
    ["Cracked Skull Soldiers in the Mills are level 9 and packed close. Start in the fields to the south and pull singly."] = "the Mills의 Cracked Skull Soldier는 9레벨이고 붙어 있어요. 남쪽 들판부터 시작해서 하나씩 풀링하세요.",
    ["Crafted Light Shot"] = "수제 소형 탄환",
    ["Craven Drok walks around the Cleft of Shadow rather than standing in one spot."] = "크라벤 드록은 한 곳에 서 있지 않고 Cleft of Shadow를 돌아다녀요.",
    ["Crimson Silk Pantaloons"] = "심홍색 비단 바지",
    ["Crimson Silk Vest"] = "심홍색 비단 조끼",
    ["Croaky drops his head, and it starts this quest."] = "Croaky가 머리를 드랍하고, 그 머리로 이 퀘스트가 시작돼요.",
    ["Croaky is a level 11 elite. Ask around for a partner before you pull him."] = "Croaky는 레벨 11 정예예요. 풀링하기 전에 주변에서 동료를 구하세요.",
    ["Croaky swims in the river south of Guard Thomas's bridge, near the Duskwood border."] = "Croaky는 Guard Thomas의 다리 남쪽 강, 그늘숲 경계 근처를 헤엄쳐요.",
    ["Croaky, a level 11 elite murloc, swims by the Waterlogged Toolbox. Look for him before you loot it."] = "레벨 11 정예 멀록 Croaky가 물에 젖은 도구상자 옆을 헤엄쳐요. 루팅하기 전에 위치를 보세요.",
    ["Cross the mountain north of Stardust, then go up the hill by the large tree beside the shrine's mouth."] = "Stardust 북쪽의 산을 넘은 다음, 제단 입구 옆 큰 나무가 있는 언덕으로 올라가세요.",
    ["Cross the right-hand bridge where the tunnel opens. The chest is in the small room at its end."] = "굴이 열리는 곳에서 오른쪽 다리를 건너세요. 상자는 끝의 작은 방에 있어요.",
    ["Cross the slime canal into the Apothecarium."] = "점액 운하를 건너 Apothecarium으로 들어가세요.",
    ["Crossing into Market Street wakes the statue. Three waves of undead come before he does."] = "시장 거리에 들어서면 석상이 깨어나요. 그가 오기 전에 언데드 웨이브가 세 번 와요.",
    ["Crossroads, The Barrens"] = "크로스로드 (불모의 땅)",
    ["Crowd Pummel hits everyone near him and stops their casts, so casters stay back."] = "고철 압축은 주변 모두를 때리고 시전을 끊어요. 원거리 캐릭터는 떨어져 있으세요.",
    ["Crowd Pummel knocks everyone round him back, behind him too. Tank with a wall at your back and keep off the platform's edge."] = "고철 압축은 주위 모두를, 뒤쪽까지 밀쳐내요. 벽을 등지고 탱킹하고 단상 가장자리에 가지 마세요.",
    ["Crowd Pummeler 9-60"] = "고철 압축기 9-60",
    ["Crowd-control one guard, and stun him as he nears half health to stop the second pair."] = "경비병 하나는 군중 제어하고, 생명력 절반 가까이 되면 기절시켜 두 번째 쌍을 막으세요.",
    ["Crowd-control one of the prisoners by him and kill the other first."] = "그 옆 죄수 중 하나는 군중 제어하고 다른 하나부터 처치하세요.",
    ["Cure Ghoul Plague at once: it lasts 30 minutes."] = "구울 역병은 30분 지속되니 바로 치료하세요.",
    ["Cure his poison if you can."] = "가능하면 그의 독을 해제하세요.",
    ["Cure the poison on the tank."] = "탱커의 독을 해제하세요.",
    ["Cured Heavy Hide"] = "질긴 경화 가죽",
    ["Cured Light Hide"] = "얇은 경화 가죽",
    ["Cured Medium Hide"] = "일반 경화 가죽",
    ["Cured Thick Hide"] = "두꺼운 경화 가죽",
    ["Curiously Tasty Omelet"] = "진기한 맛의 오믈렛",
    ["Curse of Thorns makes your own attacks hurt you."] = "가시의 저주는 자신의 공격이 자신을 다치게 만들어요.",
    ["Cursed Darkhounds roam among the ones you need, and they're higher level. Look around before each pull."] = "필요한 몹 사이로 레벨이 더 높은 Cursed Darkhound가 돌아다녀요. 풀링마다 주위를 보세요.",
    ["Cylina Darkheart is on the inn's lower floor."] = "실리나 다크하트는 여관 아래층에 있어요.",
    ["Daggerfang roams the east shore of the loch, so it may not be at the arrow."] = "Daggerfang은(는) 호수 동쪽 기슭을 돌아다녀서 화살표 위치에 없을 수 있어요.",
    ["Dal Bloodclaw is 25 and the village's furbolgs 23 to 24. Clear his path before you pull him."] = "달 블러드클로는 레벨 25이고 마을의 퍼볼그는 레벨 23~24이에요. 풀링하기 전에 그에게 가는 길을 정리하세요.",
    ["Dal Bloodclaw patrols Thistlefur Village. Look along his path if he isn't at the arrow."] = "달 블러드클로는 엉겅퀴 마을을 순찰해요. 화살표 위치에 없으면 그의 경로를 따라 찾아보세요.",
    ["Dalaran Apprentices (level 13-14) guard the crate. They cast Frostbolt and run when hurt."] = "달라란 견습마법사(레벨 13-14)가 상자를 지켜요. 얼음 화살을 쓰고 다치면 도망쳐요.",
    ["Dalaran Conjurors and Warders (16-18) hold Ambermill's east end. Keep to the Protectors and Mages west of them."] = "앰버밀 동쪽 끝은 Dalaran Conjuror와 Warder(16-18)가 지켜요. 그 서쪽의 Protector와 Mage만 상대하세요.",
    ["Dalaran and Stormwind"] = "달라란과 스톰윈드",
    ["Dalmond is indoors. He also sells Sharp Arrows, Heavy Shots and 6-slot Small Brown Pouches."] = "달몬드는 실내에 있어요. 뾰족한 화살, Heavy Shot, 6칸 Small Brown Pouch도 팔아요.",
    ["Damage dealers kill the Mana Phantoms. Stay inside his room the whole fight, or he resets."] = "딜러는 Mana Phantom을 처치하세요. 전투 내내 방 안에 있어야 해요. 나가면 초기화돼요.",
    ["Danitha Morr is upstairs in Bandarion Keep."] = "Danitha Morr은(는) 반다리온 성채 위층에 있어요.",
    ["Dannal Stern stands in the building east of the church, at its far end."] = "다날 스턴은 교회 동쪽 건물 안쪽 끝에 서 있어요.",
    ["Daphne Stilwell not here? Another player has taken this quest. Daphne Stilwell is back about 1 min after they finish, so wait nearby. If someone is about to take it, group up first: the game offers it to the whole group."] = "대프니 스틸웰이 안 보이나요? 다른 플레이어가 이 퀘스트를 진행 중이에요. 퀘스트가 끝나고 약 1분 뒤에 대프니 스틸웰이 돌아오니 근처에서 기다리세요. 누가 곧 받으려 하면 먼저 파티를 맺으세요. 파티원 모두에게 퀘스트가 공유돼요.",
    ["Daphne Stilwell paces her field. Look round it if she isn't at the arrow."] = "대프니 스틸웰은 자기 밭을 오가요. 화살표 위치에 없으면 주변을 둘러보세요.",
    ["Daphne Stilwell wanders around her field, so she may be a few steps from the arrow."] = "대프니 스틸웰은 자기 밭을 돌아다녀서 화살표에서 몇 걸음 떨어져 있을 수 있어요.",
    ["Darcy walks about inside the Lakeshire inn."] = "달시는 레이크샤이어 여관 안을 돌아다녀요.",
    ["Dark Cleric Beryl is upstairs in the Brill inn."] = "어둠의사제 베릴은 브릴 여관 위층에 있어요.",
    ["Dark Enforcers (level 10-12) hit hard and have an instant strike. Neophytes hit hard too. Fight at full health."] = "어둠의 집행자(레벨 10-12)는 세게 때리고 즉시 공격도 있어요. Neophyte도 세게 때려요. 생명력이 가득할 때 싸우세요.",
    ["Dark Iron Saboteurs can blow themselves up (Sapper Explode), burning anyone close. Keep your health high near one."] = "Dark Iron Saboteur은(는) 자폭할 수 있고(공병 폭발), 가까이 있는 모두를 태워요. 근처에서는 생명력을 높게 유지하세요.",
    ["Dark Iron Spies drop the Dark Iron Map. Right-click it to start this quest."] = "Dark Iron Spy가 검은무쇠 지도를 드랍해요. 오른쪽 클릭으로 이 퀘스트를 시작하세요.",
    ["Dark Iron Spies drop the Dark Iron Map. Use it to start this quest."] = "Dark Iron Spy가 검은무쇠 지도를 드랍해요. 사용해서 이 퀘스트를 시작하세요.",
    ["Dark Strand Voidcallers of 28 to 29 stand inside the tower itself. Keep to the Fanatics outside it."] = "레벨 28-29 Dark Strand Voidcaller는 탑 안에 있어요. 탑 밖의 Fanatic만 상대하세요.",
    ["Darkshire, Duskwood"] = "다크샤이어 (그늘숲)",
    ["Darkshore"] = "어둠의 해안",
    ["Darsok Swiftdagger is up the Crossroads tower, at its very top."] = "달소크 스위프트대거는 크로스로드 탑 맨 꼭대기에 있어요.",
    ["David Trias is inside the building east of the church."] = "데이비드 트리아스는 교회 동쪽 건물 안에 있어요.",
    ["Dawn Brightstar keeps only a few scrolls and potions, so check what she has left."] = "던 브라이트스타는 두루마리와 물약을 조금만 갖고 있으니 남은 게 있는지 확인하세요.",
    ["Deadmines"] = "죽음의 폐광",
    ["Death Speaker Jargba"] = "죽음의예언자 잘그바",
    ["Deathguard Bartholomew walks around the Brill graveyard, so he may not be at the arrow."] = "죽음의경비병 바르솔로뮤는 브릴 묘지 주위를 돌아다녀서 화살표 위치에 없을 수 있어요.",
    ["Deathguard Burgess is inside the Brill town hall."] = "죽음의경비병 버제스는 브릴 마을회관 안에 있어요.",
    ["Deathstalker Erland isn't always at his post. If he's gone, wait for him to come back."] = "죽음의추적자 엘런드가 항상 자리에 있지는 않아요. 없으면 돌아올 때까지 기다리세요.",
    ["Deathstalker Erland not here? Another player has taken this quest. Deathstalker Erland is back about 5 min after they finish, so wait nearby. If someone is about to take it, group up first: the game offers it to the whole group."] = "죽음의추적자 엘런드가 안 보이나요? 다른 플레이어가 이 퀘스트를 진행 중이에요. 퀘스트가 끝나고 약 5분 뒤에 죽음의추적자 엘런드가 돌아오니 근처에서 기다리세요. 누가 곧 받으려 하면 먼저 파티를 맺으세요. 파티원 모두에게 퀘스트가 공유돼요.",
    ["Deathstalker Faerleia waits inside Pyrewood's chapel."] = "죽음의추적자 페를레이아는 Pyrewood 예배당 안에서 기다려요.",
    ["Debilitate hits everyone within 45 yards and drains 200 mana. The group runs dry fast."] = "쇠약은 45미터 안의 모두에게 걸려 마나를 200 빼앗아요. 파티 마나가 금방 바닥나요.",
    ["Decrepit Darkhound (level 5-6) can come near the water here."] = "광포한 암흑사냥개(레벨 5-6)가 여기 물가 근처로 올 수 있어요.",
    ["Deeper in, the Young Wendigos (5-6) give way to Wendigos (6-7)."] = "더 안쪽에서는 새끼 웬디고(5-6) 대신 웬디고(6-7)가 나와요.",
    ["Deepmoss Hatchlings can call a level 22 Deepmoss Matriarch into the fight. Kill them fast, at full health."] = "Deepmoss Hatchling은(는) 레벨 22 동굴이끼 우두머리거미를 싸움에 부를 수 있어요. 생명력이 가득할 때 빨리 처치하세요.",
    ["Defias Bandits drop the deed only rarely. If it never shows, carry on without it."] = "Defias Bandit은(는) 증서를 아주 드물게 드랍해요. 끝내 안 나오면 없이 진행하세요.",
    ["Defias Highwaymen (17-18) backstab for double damage. Keep them in front of you and pull one at a time."] = "데피아즈단 노상강도(17-18)는 등 뒤에서 두 배 피해를 줘요. 정면에 두고 하나씩 풀링하세요.",
    ["Defias Miners stand around him and join the pull."] = "Defias Miner가 그 주위에 서 있다가 같이 끌려와요.",
    ["Defias Raiders (17-18) attack Daphne in three waves of 3, 4 and 5. If she or you die, the quest fails."] = "Defias Raider(17-18)가 3, 4, 5마리씩 세 웨이브로 Daphne를 공격해요. 그녀나 당신이 죽으면 퀘스트 실패예요.",
    ["Defias Thugs at the camp are level 3 and 4. Slip between them to the tent."] = "야영지의 Defias Thug는 레벨 3과 4예요. 그 사이로 빠져 막사로 가세요.",
    ["Defias Trappers root you with Net for 9 seconds and backstab. Fight them one at a time and face them."] = "Defias Trapper는 그물로 9초 동안 묶고 등 뒤를 찔러요. 하나씩 정면에서 상대하세요.",
    ["Defias attack the escort when it reaches Moonbrook. Stay at the Traitor's side all the way."] = "호위 대상이 문브룩에 닿으면 Defias가 공격해요. 끝까지 Traitor 곁에 있으세요.",
    ["Defias in Moonbrook rush the Traitor when he arrives. Stay at his side the whole way."] = "Traitor가 문브룩에 도착하면 그곳 Defias가 덤벼요. 끝까지 곁에 있으세요.",
    ["Defias respawn faster while you keep killing here. Stay in one spot and watch for new ones spawning beside you."] = "여기서 계속 잡으면 Defias가 더 빨리 재생성돼요. 한곳에 머물며 옆에 새로 생기는 몹을 조심하세요.",
    ["Demonology"] = "악마",
    ["Denalan plays a short scene first. Boglings (level 5) show up during it and drop Bogling Roots."] = "데날란이 먼저 짧은 장면을 보여 줘요. 그동안 새끼 늪괴물(레벨 5)이 나타나 Bogling Root를 떨어뜨려요.",
    ["Dendrite Starblaze is on an upper floor in Nighthaven."] = "덴드리트 스타블레이즈는 나이트헤이븐의 위층에 있어요.",
    ["Dendrite Starblaze is upstairs in Nighthaven."] = "덴드리트 스타블레이즈는 나이트헤이븐 위층에 있어요.",
    ["Dendrite Starblaze is upstairs."] = "덴드리트 스타블레이즈는 위층에 있어요.",
    ["Deviate Guardians call for help when they're low. Kill them fast."] = "Deviate Guardian은 생명력이 낮으면 도움을 불러요. 빨리 처치하세요.",
    ["Deviates in the outer caves drop hides too. One run has enough for about three players, so top up outside."] = "바깥 동굴의 Deviate도 가죽을 드랍해요. 한 번 돌면 세 명쯤 몫이 나오니 부족하면 밖에서 채우세요.",
    ["Dewin Shimmerdawn sells a few Healing Potions. Buy what you can afford."] = "데윈 심머던은 치유 물약을 몇 개 팔아요. 살 수 있는 만큼 사세요.",
    ["Dextren Ward"] = "덱스트렌 워드",
    ["Diseased Wolf (LvL. 54), Diseased Black Bear (LvL. 52), Diseased Grizzly (LvL. 56). About 15 skins on a 10-spot loop."] = "역병에 걸린 늑대 (LvL. 54), 오염된 흑곰 (LvL. 52), 오염된 불곰 (LvL. 56). 10곳을 도는 순환로에서 가죽 약 15개.",
    ["Diseased Wolf, Diseased Black Bear, Diseased Grizzly"] = "역병에 걸린 늑대, 오염된 흑곰, 오염된 불곰",
    ["Disenchant the Crude Wax Effigies the Kobold Geomancers drop to get Luminous Residue."] = "Kobold Geomancer가 드랍하는 Crude Wax Effigy를 마력 추출하면 희미하게 빛나는 잔류물이 나와요.",
    ["Disenchant the Hexed Pendants from Hexed and Voodoo Trolls. That gives the Luminous Residue."] = "Hexed Troll과 Voodoo Troll의 Hexed Pendant를 마력 추출하세요. 희미하게 빛나는 잔류물이 나와요.",
    ["Disenchanting gives skill too: a point for every item up to 20, then now and then up to 60."] = "마력 추출로도 숙련도가 올라요. 20까지는 아이템마다 1점씩, 그 뒤 60까지는 가끔 올라요.",
    ["Dismiss the Nightsaber Stalker, then target a Strigid Screecher and use the Taming Rod."] = "긴발톱 흑호를 소환 해제하고 비명소리 스트리기드 올빼미를 대상으로 잡은 뒤 조련용 막대를 사용하세요.",
    ["Dismiss the Surf Crawler first, then tame the scorpid."] = "먼저 붉은톱니게를 소환 해제한 뒤 전갈을 길들이세요.",
    ["Dismiss the boar before you tame a Surf Crawler. You can only hold one beast."] = "붉은톱니게를 길들이기 전에 멧돼지를 소환 해제하세요. 야수는 하나만 데리고 있을 수 있어요.",
    ["Dismiss the boar, then target a Gray Forest Wolf and use the second Taming Rod."] = "멧돼지를 소환 해제하고 회색 숲늑대를 대상으로 잡은 뒤 두 번째 조련용 막대를 사용하세요.",
    ["Dismiss the last beast you tamed first, or the Taming Rod won't take a new one."] = "마지막으로 길들인 야수를 먼저 소환 해제하세요. 아니면 조련용 막대가 새 야수를 받지 않아요.",
    ["Dismiss the wolf, then target a Young Forest Bear and use the third Taming Rod."] = "늑대를 소환 해제하고 새끼 숲곰을 대상으로 잡은 뒤 세 번째 조련용 막대를 사용하세요.",
    ["Dismiss your pet, then target a Nightsaber Stalker and use the Taming Rod."] = "소환수를 소환 해제하고 긴발톱 흑호를 대상으로 잡은 뒤 조련용 막대를 사용하세요.",
    ["Dispel or purge her Renew. When she shields herself, wait it out: it clears your debuffs on her."] = "그녀의 소생을 해제하거나 정화하세요. 스스로 보호막을 걸면 기다리세요. 그녀에게 건 디버프가 지워져요.",
    ["Dive for a Shrine Bauble in a Bauble Container on the lake bed, then take it to the Shrine of Remulos."] = "호수 바닥의 Bauble Container에서 제단 구슬을 건져 레물로스의 제단으로 가져가세요.",
    ["Dive into the pool among the ruins. The cave under the water leads past naga to the portal. Watch your breath."] = "폐허 사이 웅덩이로 잠수하세요. 물속 동굴이 나가 사이를 지나 차원문으로 이어져요. 숨을 확인하세요.",
    ["Doan Karhan takes it once you carry all four fragments, from this run and Blackfathom Deeps."] = "이번 던전과 검은심연 나락에서 얻은 조각 네 개를 모두 가지면 도안 카르한에게 완료할 수 있어요.",
    ["Doan Karhan takes it once you carry all four fragments, from this run and Shadowfang Keep."] = "이번 던전과 그림자송곳니 성채에서 얻은 조각 네 개를 모두 가지면 도안 카르한에게 완료할 수 있어요.",
    ["Doc Mixilpixil is in the cellar below SI:7. Take the stairs down."] = "닥 믹실픽실은 SI:7 아래 지하실에 있어요. 계단으로 내려가세요.",
    ["Doctor Martin Felben is in the Apothecarium, over the slime canal."] = "박사 마틴 펠벤은 점액 수로 위 Apothecarium에 있어요.",
    ["Dogran's Pendant calls the succubus at the Summoning Circle. Use it there, then kill her."] = "도그란의 목걸이는 Summoning Circle에서 서큐버스를 불러요. 거기서 사용한 뒤 그녀를 처치하세요.",
    ["Don't drag him into the water: he resets."] = "물속으로 끌고 가지 마세요. 초기화돼요.",
    ["Don't fall off the central structure. Mobs below walk round with about a dozen more."] = "가운데 구조물에서 떨어지지 마세요. 아래 몹은 열두 마리쯤 더 데리고 돌아다녀요.",
    ["Don't vendor the eyes, snouts, vulture meat or livers. Salma takes all of them."] = "눈알, 주둥이, 독수리 고기, 간은 상인에게 팔지 마세요. Salma가 모두 받아요.",
    ["Donyal Tovald is in the library inside Stormwind Keep."] = "도니얼 토발드는 스톰윈드 성 안 도서관에 있어요.",
    ["Doom Weed grows at the foot of trees in the Rot Hide gnoll camps."] = "죽음풀은 Rot Hide 놀 야영지의 나무 밑동에 자라요.",
    ["Doras stands at the top of the wind rider tower."] = "도라스는 와이번 탑 꼭대기에 서 있어요.",
    ["Dorn Plainstalker waits in a small cave up the ramp."] = "도른 플레인스토커는 경사로 위 작은 동굴에서 기다려요.",
    ["Double-stitched Woolen Shoulders"] = "이중 양모 어깨보호구",
    ["Down in the Pools of Vision, the cave under Spirit Rise. Go in by the cave mouth beside the bridge up to the rise."] = "정기의 봉우리 아래 동굴, 예언의 웅덩이 안에 있어요. 봉우리로 올라가는 다리 옆 동굴 입구로 들어가세요.",
    ["Drag him downhill to Rudra Amberstill and the guard posted at the ranch's south end. With their help you can kill him alone."] = "그를 언덕 아래 루드라 앰버스틸과 농장 남쪽 끝의 경비병에게 끌고 가세요. 그들의 도움으로 혼자서도 잡을 수 있어요.",
    ["Drag it through the campfires to burn it."] = "모닥불 사이로 끌고 다니며 태우세요.",
    ["Draw the apprentices away one at a time, then open the crate."] = "수습생을 하나씩 끌어낸 뒤 상자를 여세요.",
    ["Dreamfoil (skill 270), Golden Sansam (skill 260), Sungrass (skill 230), Arthas' Tears (skill 220), Mountain Silversage (skill 280). About 20 nodes on a 10-spot loop."] = "꿈풀 (숙련도 270), 황금 산삼 (숙련도 260), 태양풀 (숙련도 230), 아서스의 눈물 (숙련도 220), 은초롱이 (숙련도 280). 10곳을 도는 순환로에서 채집물 약 20개.",
    ["Dreamfoil, Golden Sansam, Sungrass"] = "꿈풀, 황금 산삼, 태양풀",
    ["Drink the Earth Sapta at the Rise of Spirits, then talk to the Minor Manifestation of Earth."] = "정령의 오르막에서 대지의 정기를 마신 뒤 하급 대지의 현신과 대화하세요.",
    ["Drink the Earth Sapta at the shrine, and the Minor Manifestation of Earth appears."] = "성소에서 대지의 정기를 마시면 하급 대지의 현신이 나타나요.",
    ["Drink the Fire Sapta by the shrine so the Minor Manifestation of Fire shows itself."] = "하급 불의 현신이 모습을 드러내도록 성소 옆에서 불의 정기를 마시세요.",
    ["Drones, the Malformed one too, can be waiting at the door on your way out. Keep Sprint ready."] = "나갈 때 문 앞에 Drone(Malformed 포함)이 기다릴 수 있어요. 전력 질주를 준비해 두세요.",
    ["Drop down behind Charlga's platform. Willix is in the tent below."] = "Charlga의 단상 뒤로 내려가세요. Willix는 아래 천막에 있어요.",
    ["Dropping into the hold from the slope above lands you among the trolls. Clear your way in on foot."] = "위쪽 비탈에서 요새로 뛰어내리면 트롤 한가운데 떨어져요. 걸어서 길을 정리하며 들어가세요.",
    ["Drudgers and Bashers share spawn points. If Drudgers run short, kill Bashers to bring more."] = "Drudger와 Basher는 생성 지점을 같이 써요. Drudger가 모자라면 Basher를 잡아 더 나오게 하세요.",
    ["Druids: Entangling Roots holds it in place once it turns, so you can back off and cast."] = "드루이드: 돌아선 뒤 휘감는 뿌리로 묶어 두면 물러나서 시전할 수 있어요.",
    ["Druids: cast Wrath while your mana lasts, then melee until it refills."] = "드루이드: 마나가 있는 동안 천벌을 쓰고, 그다음 마나가 찰 때까지 근접 공격하세요.",
    ["Druids: from here, melee plus Moonfire beats Wrath. Cast Moonfire right after a swing lands."] = "드루이드: 여기부터는 천벌보다 근접 공격과 달빛 섬광이 나아요. 평타가 들어간 직후 달빛 섬광을 쓰세요.",
    ["Druids: pick 5 Earthroot and keep them for Gathering the Cure, a level 14 quest in Auberdine."] = "드루이드: 뱀뿌리 5개를 채집해 아우버다인의 레벨 14 퀘스트 약재 모으기에 쓰게 챙기세요.",
    ["Dry Branches lie at the foot of the trees around Brill."] = "Dry Branches는 브릴 주변 나무 밑동에 있어요.",
    ["Dry Pork Ribs"] = "말린 돼지 갈비",
    ["Durgen Dirgehammer"] = "드루겐 더지해머",
    ["Duriel Moonfire appears on the balcony after the building. Let Torek's group hit her first and she stays on them."] = "건물 다음에 두리엘 문파이어가 발코니에 나타나요. 토렉 일행이 먼저 때리게 두면 그녀는 그들을 계속 상대해요.",
    ["Durnan Furcutter stands inside Anvilmar."] = "두르난 퍼커터는 앤빌마 안에 서 있어요.",
    ["Duskbat Pelts don't drop from every bat. Plan on more kills than the five you need."] = "모든 박쥐가 그늘박쥐 모피를 주진 않아요. 필요한 다섯보다 더 잡을 생각을 하세요.",
    ["Duskwood and Redridge"] = "그늘숲과 붉은마루 산맥",
    ["Dust Devils wander all over Westfall. Take each one you pass."] = "Dust Devil이 서부 몰락지대 곳곳을 돌아다녀요. 지나가며 보이는 대로 잡으세요.",
    ["Dustrunners cast Rejuvenation on themselves and Battleguards have a lot of health. Pull them one at a time."] = "Dustrunner는 자신에게 회복을 걸고 Battleguard는 생명력이 많아요. 하나씩 풀링하세요.",
    ["Dustwallow Marsh and Swamp of Sorrows are nearly as good for this."] = "먼지진흙 습지대와 슬픔의 늪도 이 용도로 거의 비슷해요.",
    ["Dustwallow Marsh, Tanaris and Badlands are nearly as good for this."] = "먼지진흙 습지대, 타나리스, 황야의 땅도 이 용도로 거의 비슷해요.",
    ["Dustwind Savages and Storm Witches run when hurt and can bring another one back. Finish them before they get away."] = "Dustwind Savage와 Storm Witch는 다치면 도망쳐 하나를 더 데려올 수 있어요. 달아나기 전에 끝내세요.",
    ["Dustwind Storm Witches drop the Dull Storm Orb that starts this."] = "Dustwind Storm Witch가 이 퀘스트를 시작하는 희미한 폭풍 보주를 드랍해요.",
    ["Duthorian Rall is inside the Cathedral of Light."] = "두소리안 랄은 Cathedral of Light 안에 있어요.",
    ["Dwarves: Stoneform clears Touch of Zanzil."] = "드워프: 석화로 잔질의 손길을 해제할 수 있어요.",
    ["Each Kolkar killed at the oasis can bring out Verog. When it's crowded, wait at his spawn point."] = "오아시스에서 Kolkar를 잡을 때마다 Verog이(가) 나올 수 있어요. 붐비면 그의 생성 지점에서 기다리세요.",
    ["Each lockbox is on its wreck's lowest deck, deep enough to run out of breath. Watch the breath bar."] = "금고는 각 난파선 맨 아래 갑판에 있어 숨이 찰 만큼 깊어요. 호흡 바를 보세요.",
    ["Each naga's Spinefin goes to one player only, so a group needs a kill each."] = "나가의 Spinefin은 한 명에게만 떨어져서 파티는 각자 하나씩 잡아야 해요.",
    ["Each nest (blue, red and yellow) takes one Sunscale Feather, which the Scytheclaws drop."] = "둥지(파랑, 빨강, 노랑)마다 Scytheclaw가 드랍하는 열대초원랩터 깃털이 하나씩 필요해요.",
    ["Each relic is a small orb beside a cat statue in a wall alcove. The Relic of the Claw is deepest, past a bridge."] = "유물은 벽감 속 고양이 석상 옆의 작은 구슬이에요. 발톱의 성물은 다리 건너 가장 깊은 곳에 있어요.",
    ["Each report comes from a dialogue option when you talk to Kristof, Dillinger and Gordo."] = "Kristof, Dillinger, 고르도와 대화할 때 대화 선택지로 보고서를 하나씩 얻어요.",
    ["Each sack takes 5 seconds to open. Clear mobs close by first so nothing hits you mid-cast."] = "자루 하나 여는 데 5초 걸려요. 시전 중에 맞지 않게 가까운 몹을 먼저 정리하세요.",
    ["Each teleport wipes his threat. Hold your damage until the tank has him again."] = "순간이동할 때마다 위협 수준이 초기화돼요. 탱커가 다시 잡을 때까지 딜을 멈추세요.",
    ["Eagan Peltskinner stands outdoors, beside the abbey."] = "이건 펠트스키너는 야외, 수도원 옆에 서 있어요.",
    ["Earthroot takes Herbalism 15. Without it, look in Battered Chests or the Auction House."] = "뱀뿌리에는 약초채집 15가 필요해요. 없으면 Battered Chest나 경매장을 찾아보세요.",
    ["Eastern Plaguelands and Western Plaguelands are nearly as good for this."] = "동부 역병지대와 서부 역병지대도 이 용도로 거의 비슷해요.",
    ["Eastern Plaguelands is nearly as good for this."] = "동부 역병지대도 이 용도로 거의 비슷해요.",
    ["Eat and drink in each lull between worg attacks."] = "늑대 공격 사이 쉬는 틈마다 먹고 마시세요.",
    ["Ebru stands next to Nalpak in the hidden cave above the cave mouth. Take the path up from the meeting stone."] = "에브루는 동굴 입구 위 숨은 동굴에서 날팍 옆에 서 있어요. 만남의 돌에서 올라가는 길로 가세요.",
    ["Edward's body lies by the graves next to Rath'mael. Stand on it."] = "Edward의 시체는 라스마엘 옆 무덤가에 있어요. 그 위에 서세요.",
    ["Edwin VanCleef"] = "에드윈 밴클리프",
    ["Edwin VanCleef (level 21 elite) is the Deadmines' last boss. Take this only for a group run."] = "에드윈 밴클리프(레벨 21 정예)는 죽음의 폐광의 마지막 우두머리예요. 파티로 갈 때만 받으세요.",
    ["Elaine Carevin is indoors."] = "일레인 카레빈은 실내에 있어요.",
    ["Elaine Trias waits in the shop below the door."] = "일레인 트리아스는 문 아래 상점에서 기다려요.",
    ["Elayaa Easewind trains hunters inside a house."] = "Elayaa Easewind은(는) 집 안에서 사냥꾼을 가르쳐요.",
    ["Elder Darkshore Threshers (16-18) swim among the 12-14 ones. Pull the smaller ones."] = "덩치큰 어둠의해안 트레샤돈(16-18)이 12-14 레벨 무리 사이를 헤엄쳐요. 작은 쪽을 풀링하세요.",
    ["Elder Finseer, a level 11 rare murloc, walks Stone Cairn Lake's shore among the huts. Croaky, an 11 elite, stays in the river south of the bridge."] = "레벨 11 희귀 멀록 Elder Finseer은(는) 오두막 사이 돌무덤 호수 기슭을 걸어요. 11 정예 Croaky는 다리 남쪽 강에 있어요.",
    ["Elder Gray Bear (LvL. 26), Gray Bear (LvL. 22), Vicious Gray Bear (LvL. 22), Starving Mountain Lion (LvL. 24), Feral Mountain Lion (LvL. 28). About 42 skins on a 10-spot loop."] = "덩치큰 회색곰 (LvL. 26), 회색곰 (LvL. 22), 흉포한 회색곰 (LvL. 22), 굶주린 산사자 (LvL. 24), 흉포한 산사자 (LvL. 28). 10곳을 도는 순환로에서 가죽 약 42개.",
    ["Elder Gray Bear (LvL. 26), Starving Mountain Lion (LvL. 24), Feral Mountain Lion (LvL. 28), Snapjaw (LvL. 30), Gray Bear (LvL. 22), Vicious Gray Bear (LvL. 22). About 29 skins on a 10-spot loop."] = "덩치큰 회색곰 (LvL. 26), 굶주린 산사자 (LvL. 24), 흉포한 산사자 (LvL. 28), 무쇠턱거북 (LvL. 30), 회색곰 (LvL. 22), 흉포한 회색곰 (LvL. 22). 10곳을 도는 순환로에서 가죽 약 29개.",
    ["Elder Gray Bear, Gray Bear, Vicious Gray Bear"] = "덩치큰 회색곰, 회색곰, 흉포한 회색곰",
    ["Elder Gray Bear, Starving Mountain Lion, Feral Mountain Lion"] = "덩치큰 회색곰, 굶주린 산사자, 흉포한 산사자",
    ["Elder Gray Bears (25-26) and Elder Moss Creepers (26-27) outlevel the rest here. Leave them alone."] = "덩치큰 회색곰(25-26)과 덩치큰 이끼거미(26-27)는 여기서 레벨이 높아요. 건드리지 마세요.",
    ["Elder Mottled Boar (LvL. 8), Dire Mottled Boar (LvL. 6), Clattering Scorpid (LvL. 6), Armored Scorpid (LvL. 8), Venomtail Scorpid (LvL. 10), Durotar Tiger (LvL. 8). About 95 skins on a 10-spot loop."] = "덩치큰 점박이멧돼지 (LvL. 8), 사나운 점박이멧돼지 (LvL. 6), 집게발전갈 (LvL. 6), 등껍질전갈 (LvL. 8), 맹독전갈 (LvL. 10), 듀로타 호랑이 (LvL. 8). 10곳을 도는 순환로에서 가죽 약 95개.",
    ["Elder Mottled Boar, Dire Mottled Boar, Clattering Scorpid"] = "덩치큰 점박이멧돼지, 사나운 점박이멧돼지, 집게발전갈",
    ["Elder Mountain Boar (LvL. 16), Black Bear Patriarch (LvL. 16), Mangy Mountain Boar (LvL. 14), Loch Crocolisk (LvL. 14), Mountain Boar (LvL. 10), Elder Black Bear (LvL. 12). About 78 skins on a 10-spot loop."] = "덩치큰 산돼지 (LvL. 16), 우두머리 흑곰 (LvL. 16), 병든 산돼지 (LvL. 14), 호수악어 (LvL. 14), 산돼지 (LvL. 10), 덩치큰 흑곰 (LvL. 12). 10곳을 도는 순환로에서 가죽 약 78개.",
    ["Elder Mountain Boar, Black Bear Patriarch, Mangy Mountain Boar"] = "덩치큰 산돼지, 우두머리 흑곰, 병든 산돼지",
    ["Elder Snow Leopard (LvL. 10), Elder Crag Boar (LvL. 8), Crag Boar (LvL. 6), Snow Leopard (LvL. 8), Ice Claw Bear (LvL. 8), Large Crag Boar (LvL. 6). About 79 skins on a 10-spot loop."] = "Elder 눈표범 (LvL. 10), 덩치큰 멧돼지 (LvL. 8), 멧돼지 (LvL. 6), 눈표범 (LvL. 8), 얼음발톱흰곰 (LvL. 8), 큰 멧돼지 (LvL. 6). 10곳을 도는 순환로에서 가죽 약 79개.",
    ["Elder Snow Leopard, Elder Crag Boar, Crag Boar"] = "Elder 눈표범, 덩치큰 멧돼지, 멧돼지",
    ["Electrocutioner 6000"] = "기계화 문지기 6000",
    ["Electropellers live in fresh water, not the sea: the Cliffspring River north of Auberdine, the Wildbend River, or the pond in the Grove of the Ancients."] = "전력추진기는 바다가 아니라 민물에 살아요. 아우버다인 북쪽의 폭포수 강, 성난굽이 강, 또는 고대정령의 숲의 연못에서 낚으세요.",
    ["Elemental"] = "정기",
    ["Elite Blackrock orcs of 21 to 25 camp a short way north-west of the falls."] = "레벨 21-25 정예 Blackrock 오크가 폭포 조금 북서쪽에 진을 치고 있어요.",
    ["Elite Blackrock orcs, levels 20 to 23, fill the tower. Bring a group of three."] = "레벨 20-23 정예 Blackrock 오크가 탑에 가득해요. 세 명이 가세요.",
    ["Elites patrol the open caves before the portal. Fight there as carefully as inside."] = "차원문 앞 트인 동굴에 정예가 순찰해요. 안에서처럼 조심해서 싸우세요.",
    ["Elixir of Defense"] = "방어의 비약",
    ["Elixir of Defense is an Alchemy potion. Make it, ask an alchemist, or buy it at the Auction House."] = "방어의 비약은 연금술 물약이에요. 직접 만들거나, 연금술사에게 부탁하거나, 경매장에서 사세요.",
    ["Elixir of Minor Defense"] = "최하급 방어의 비약",
    ["Elixir of Wisdom"] = "지혜의 비약",
    ["Elmpaw, level 12, roams north of Stone Cairn Lake. His head starts this quest."] = "레벨 12 Elmpaw은(는) 돌무덤 호수 북쪽을 돌아다녀요. 그의 머리로 이 퀘스트가 시작돼요.",
    ["Elune's Tear is a small blue stone lying on the lake's central island."] = "엘룬의 눈물은 호수 가운데 섬에 놓인 작은 파란 돌이에요.",
    ["Embossed Leather Gloves"] = "새김무늬 가죽 장갑",
    ["Enchant Boots - Lesser Agility"] = "장화 마법부여 - 하급 민첩성",
    ["Enchant Boots - Lesser Stamina"] = "장화 마법부여 - 하급 체력",
