    ["Maxan Anvol is inside the Thunderbrew Distillery."] = "막산 앤볼은 썬더브루 양조장 안에 있어요.",
    ["Maximillian Crowe is in the inn's basement."] = "맥시밀리언 크로우는 여관 지하에 있어요.",
    ["Maybell Maclure is inside the house at the Maclure Vineyards."] = "메이벨 맥클루어는 맥클루어 포도밭의 집 안에 있어요.",
    ["Maybell Maclure is inside the small house at the Maclure Vineyards."] = "메이벨 맥클루어는 맥클루어 포도밭의 작은 집 안에 있어요.",
    ["Mekgineer Thermaplugg"] = "기계박사 텔마플러그",
